9	)
10	
11	// 本文件实现按月累计用量的阶梯计费：方案登记与查询、绑定方案客户的
12	// 创建、阶梯计价引擎与阶梯账单结算。固定单价计费路径不受影响。
13	
14	// tieredLine 是一条用量记录的阶梯计价结果：跨档分段与本条小计。
15	type tieredLine struct {
16		segments []lineSegment
17		fee      int64
18	}
19	
20	// tieredResult 是一组用量记录按阶梯规则计价后的完整结果。
21	type tieredResult struct {
22		lines    []tieredLine // 与输入记录一一对应
23		tierQty  []int64      // 各档实际数量（与方案档位顺序对齐）
24		tierFee  []int64      // 各档实际金额（分）
25		totalQty int64
26		totalFee int64
27	}
28	
29	// tieredPrice 按阶梯规则对一组已按（解析后的时间点升序、同一时间按标识
30	// 字典序）排列的用量记录从月累计零开始计价：每条记录按当时累计量落入的
31	// 档位分段，各档仅对落入本档的数量收费，不把最高档价格套用全月，也不对
32	// 每条用量重置阶梯。全程整数运算；月累计数量、分档金额或总额溢出有符号
33	// 64 位范围时返回错误。
34	func tieredPrice(tiers []tier, recs []*usageRecord) (*tieredResult, error) {
35		res := &tieredResult{
36			lines:   make([]tieredLine, len(recs)),
37			tierQty: make([]int64, len(tiers)),
38			tierFee: make([]int64, len(tiers)),
39		}
40		var cum int64 // 月累计数量
41		tierIdx := 0  // 当前档位（单调前进，不回退）
42		for i, u := range recs {
43			remaining := u.Quantity
44			var lineFee int64
45			var segs []lineSegment
46			for remaining > 0 {
47				// 累计量越过当前档上限时前进到下一档；上限严格递增，
48				// 因此前进后当前档剩余容量必为正。
49				for tierIdx < len(tiers)-1 && cum >= tiers[tierIdx].Limit {
50					tierIdx++
51				}
52				t := tiers[tierIdx]
53				take := remaining
54				if tierIdx < len(tiers)-1 && take > t.Limit-cum {
55					take = t.Limit - cum
56				}
57				fee, err := mul64(take, t.Price)
58				if err != nil {
59					return nil, fmt.Errorf("用量 %s：第 %d 档数量 %d × 单价 %d 金额溢出", u.ID, tierIdx+1, take, t.Price)
60				}
61				if lineFee, err = add64(lineFee, fee); err != nil {
62					return nil, fmt.Errorf("用量 %s：分段小计汇总溢出", u.ID)
63				}
64				if cum, err = add64(cum, take); err != nil {
65					return nil, fmt.Errorf("月累计数量溢出")
66				}
67				if res.tierQty[tierIdx], err = add64(res.tierQty[tierIdx], take); err != nil {
68					return nil, fmt.Errorf("第 %d 档累计数量溢出", tierIdx+1)
69				}
70				if res.tierFee[tierIdx], err = add64(res.tierFee[tierIdx], fee); err != nil {
71					return nil, fmt.Errorf("第 %d 档累计金额溢出", tierIdx+1)
72				}
73				segs = append(segs, lineSegment{Tier: tierIdx, Quantity: take, Fee: fee})
74				remaining -= take
75			}
76			res.lines[i] = tieredLine{segments: segs, fee: lineFee}
77			var err error
78			if res.totalQty, err = add64(res.totalQty, u.Quantity); err != nil {
79				return nil, fmt.Errorf("汇总数量溢出")
80			}
81			if res.totalFee, err = add64(res.totalFee, lineFee); err != nil {
82				return nil, fmt.Errorf("汇总金额溢出")
83			}
84		}
85		return res, nil
86	}
87	
88	// parseTierSpecs 解析阶梯参数：每档为 <上限>:<单价分>，上限为正整数且
89	// 严格递增；最后一档用 - 表示无上限（-:<单价分>）。至少一档。
90	func parseTierSpecs(args []string) ([]tier, error) {
91		if len(args) == 0 {
92			return nil, fmt.Errorf("阶梯方案至少需要一档，格式：<上限>:<单价分>，最后一档用 -:<单价分> 表示无上限")
93		}
94		tiers := make([]tier, 0, len(args))
95		prev := int64(0)
96		for i, arg := range args {
97			parts := strings.Split(arg, ":")
98			if len(parts) != 2 {
99				return nil, fmt.Errorf("阶梯档 %q 格式非法，应为 <上限>:<单价分>（如 100:10），最后一档用 -:<单价分> 表示无上限", arg)
100			}
101			last := i == len(args)-1
102			limitText := strings.TrimSpace(parts[0])
103			var limit int64
104			if limitText == "-" {
105				if !last {
106					return nil, fmt.Errorf("阶梯档 %q：只有最后一档可以无上限（-:<单价分>）", arg)
107				}
108			} else {
109				v, err := strconv.ParseInt(limitText, 10, 64)
110				if err != nil {
111					return nil, fmt.Errorf("阶梯档 %q 的上限 %q 不是有符号 64 位整数: %w", arg, parts[0], err)
112				}
113				if v <= 0 {
114					return nil, fmt.Errorf("阶梯档 %q 的上限必须是正整数，收到 %d", arg, v)
115				}
116				if v <= prev {
117					return nil, fmt.Errorf("阶梯档 %q 的上限 %d 未严格大于上一档上限 %d", arg, v, prev)
118				}
119				if last {
120					return nil, fmt.Errorf("最后一档必须无上限，请用 -:<单价分> 表示（如 -:%s）", parts[1])
121				}
122				prev = v
123				limit = v
124			}
125			price, err := parsePrice(parts[1])
126			if err != nil {
127				return nil, fmt.Errorf("阶梯档 %q 的单价无效: %w", arg, err)
128			}
129			tiers = append(tiers, tier{Limit: limit, Price: price})
130		}
131		return tiers, nil
132	}
133	
134	// formatTiers 以 "100:10 500:8 -:5" 形式紧凑展示阶梯规则。
135	func formatTiers(tiers []tier) string {
136		parts := make([]string, len(tiers))
137		for i, t := range tiers {
138			limit := "-"
139			if t.Limit != 0 {
140				limit = strconv.FormatInt(t.Limit, 10)
141			}
142			parts[i] = fmt.Sprintf("%s:%d", limit, t.Price)
143		}
144		return strings.Join(parts, " ")
145	}
