147	// printPlan 输出一个阶梯计费方案的完整规则。
148	func printPlan(p *plan) {
149		fmt.Fprintf(stdout, "方案标识：%s\n", p.ID)
150		fmt.Fprintf(stdout, "方案名称：%s\n", p.Name)
151		fmt.Fprintln(stdout, "阶梯规则（按 UTC 自然月累计用量分档计价，每月从零累计）：")
152		for i, t := range p.Tiers {
153			if t.Limit == 0 {
154				fmt.Fprintf(stdout, "  第 %d 档：累计数量无上限，单价 %d 分（%s）\n", i+1, t.Price, moneyFen(t.Price))
155			} else {
156				fmt.Fprintf(stdout, "  第 %d 档：累计上限 %d，单价 %d 分（%s）\n", i+1, t.Limit, t.Price, moneyFen(t.Price))
157			}
158		}
159	}
