161	func cmdPlanAdd(dir, id, name string, tierArgs []string) error {
162		if strings.TrimSpace(id) == "" {
163			return fmt.Errorf("方案标识不能为空")
164		}
165		if strings.TrimSpace(name) == "" {
166			return fmt.Errorf("方案名称不能为空")
167		}
168		tiers, err := parseTierSpecs(tierArgs)
169		if err != nil {
170			return err
171		}
172	
173		s, err := loadStore(dir)
174		if err != nil {
175			return err
176		}
177		if _, exists := s.Plans[id]; exists {
178			return fmt.Errorf("方案标识 %q 已存在，方案创建后不可修改", id)
179		}
180		p := &plan{ID: id, Name: name, Tiers: tiers}
181		s.Plans[id] = p
182	
183		// 方案整体原子落盘；保存失败则一切不生效，该方案标识不被占用。
184		if err := s.save(); err != nil {
185			delete(s.Plans, id)
186			return err
187		}
188		fmt.Fprintf(stdout, "已登记阶梯计费方案 %q（%s）：\n\n", id, name)
189		printPlan(p)
190		return nil
191	}
