228	func cmdCustomerAddPlan(dir, id, name, planID string) error {
229		if strings.TrimSpace(id) == "" {
230			return fmt.Errorf("客户标识不能为空")
231		}
232		if strings.TrimSpace(name) == "" {
233			return fmt.Errorf("客户名称不能为空")
234		}
235		if strings.TrimSpace(planID) == "" {
236			return fmt.Errorf("方案标识不能为空")
237		}
238	
239		s, err := loadStore(dir)
240		if err != nil {
241			return err
242		}
243		p, ok := s.Plans[planID]
244		if !ok {
245			return fmt.Errorf("方案标识 %q 不存在", planID)
246		}
247		if _, exists := s.Customers[id]; exists {
248			return fmt.Errorf("客户标识 %q 已存在，客户创建后不可修改", id)
249		}
250		s.Customers[id] = &customer{ID: id, Name: name, PlanID: planID}
251	
252		// 客户整体原子落盘；保存失败则一切不生效，该客户标识不被占用。
253		if err := s.save(); err != nil {
254			delete(s.Customers, id)
255			return err
256		}
257		fmt.Fprintf(stdout, "已登记客户 %q（%s），绑定阶梯计费方案 %q（%s），绑定不可变更\n", id, name, planID, p.Name)
258		return nil
259	}
260	
261	// settleTiered 对绑定阶梯方案的客户按 UTC 自然月累计用量分档计价并封账。
262	// recs 已按计价顺序（时间点升序、同一时间按标识字典序）排列。
263	// 月累计数量、分档金额或总额溢出时拒绝结算且不封账。
264	func settleTiered(s *state, cust *customer, month string, recs []*usageRecord) error {
265		b, err := buildTieredBill(s, cust, month, recs)
266		if err != nil {
267			return fmt.Errorf("客户 %s 的 %s 阶梯计价失败，拒绝结算且不封账: %w", cust.ID, month, err)
268		}
269		key := billKey(cust.ID, month)
270		s.Bills[key] = b
271	
272		// 账单与封账状态在同一次原子保存中一起持久化；保存失败则一切不生效。
273		if err := s.save(); err != nil {
274			delete(s.Bills, key)
275			return err
276		}
277		fmt.Fprintf(stdout, "结算完成，客户 %s 的 %s 已封账（阶梯计费）：\n\n", cust.ID, month)
278		printBill(b, cust, s)
279		return nil
280	}
281	
282	// buildTieredBill 为绑定阶梯方案的客户构造阶梯账单（不落盘）：采用账期月的
283	// 有效方案（初始绑定被生效月不晚于账期月的最后一次变更替换）从零累计分档
284	// 计价，账单保存方案标识、名称与完整规则快照。recs 须已按计价顺序排列。
285	// 月累计数量、分档金额或总额溢出时返回错误。
286	func buildTieredBill(s *state, cust *customer, month string, recs []*usageRecord) (*bill, error) {
287		p := s.Plans[s.effectivePlanID(cust, month)] // 载入时已校验存在
288		priced, err := tieredPrice(p.Tiers, recs)
289		if err != nil {
290			return nil, err
291		}
292	
293		lines := make([]billLine, len(recs))
294		for i, u := range recs {
295			lines[i] = billLine{
296				UsageID:  u.ID,
297				Time:     u.Time,
298				Quantity: u.Quantity,
299				LineFee:  priced.lines[i].fee,
300				Segments: priced.lines[i].segments,
301			}
302		}
303		tierTotals := make([]tierTotal, len(p.Tiers))
304		for i := range p.Tiers {
305			tierTotals[i] = tierTotal{Quantity: priced.tierQty[i], Fee: priced.tierFee[i]}
306		}
307		// 账单保存方案标识、名称与完整规则快照，之后计价与校验只依赖账单自身。
308		tiersCopy := make([]tier, len(p.Tiers))
309		copy(tiersCopy, p.Tiers)
310		return &bill{
311			ID:         stableBillID(cust.ID, month),
312			CustomerID: cust.ID,
313			Month:      month,
314			Pricing:    "tiered",
315			PlanID:     p.ID,
316			PlanName:   p.Name,
317			PlanTiers:  tiersCopy,
318			TierTotals: tierTotals,
319			TotalQty:   priced.totalQty,
320			TotalFee:   priced.totalFee,
321			Lines:      lines,
322			CreatedAt:  time.Now().UTC().Format(time.RFC3339),
323		}, nil
324	}
