266	// validate 对读入的库做一致性检查，任何异常都按损坏处理。
267	func (s *state) validate() error {
268		if s.Version != stateVersion {
269			return fmt.Errorf("不支持的数据版本 %d（仅支持 %d）", s.Version, stateVersion)
270		}
271		if s.Customers == nil || s.Usage == nil || s.Bills == nil {
272			return errors.New("缺少必要的数据节")
273		}
274		for id, p := range s.Plans {
275			if p == nil {
276				return fmt.Errorf("方案 %q 的数据为空", id)
277			}
278			if p.ID != id {
279				return fmt.Errorf("方案标识不一致: 键 %q / 记录 %q", id, p.ID)
280			}
281			if err := validatePlanRules(p); err != nil {
282				return err
283			}
284		}
285		for id, c := range s.Customers {
286			if c == nil {
287				return fmt.Errorf("客户 %q 的数据为空", id)
288			}
289			if c.ID != id {
290				return fmt.Errorf("客户标识不一致: 键 %q / 记录 %q", id, c.ID)
291			}
292			if c.ID == "" || c.Name == "" {
293				return fmt.Errorf("客户 %q 的标识或名称为空", id)
294			}
295			if c.Price < 0 {
296				return fmt.Errorf("客户 %q 单价为负", id)
297			}
298			if c.PlanID != "" {
299				if _, ok := s.Plans[c.PlanID]; !ok {
300					return fmt.Errorf("客户 %q 绑定了不存在的方案 %q", id, c.PlanID)
301				}
302			}
303		}
304		// 方案变更：键、客户（须为绑定阶梯方案的客户）、目标方案、生效月与
305		// 原因都必须自洽；同一客户的变更生效月由键保证唯一。
306		for key, ch := range s.PlanChanges {
307			if ch == nil {
308				return fmt.Errorf("方案变更 %q 的数据为空", key)
309			}
310			if planChangeKey(ch.CustomerID, ch.Month) != key {
311				return fmt.Errorf("方案变更键不一致: 键 %q / 客户月份 %s|%s", key, ch.CustomerID, ch.Month)
312			}
313			c, ok := s.Customers[ch.CustomerID]
314			if !ok {
315				return fmt.Errorf("方案变更 %q 引用了不存在的客户 %q", key, ch.CustomerID)
316			}
317			if c.PlanID == "" {
318				return fmt.Errorf("方案变更 %q 的客户 %q 未绑定阶梯方案", key, ch.CustomerID)
319			}
320			if !validMonth(ch.Month) {
321				return fmt.Errorf("方案变更 %q 的生效月无效", key)
322			}
323			if _, ok := s.Plans[ch.PlanID]; !ok {
324				return fmt.Errorf("方案变更 %q 引用了不存在的方案 %q", key, ch.PlanID)
325			}
326			if strings.TrimSpace(ch.Reason) == "" {
327				return fmt.Errorf("方案变更 %q 的原因为空", key)
328			}
329		}
330		for id, u := range s.Usage {
331			if u == nil {
332				return fmt.Errorf("用量 %q 的数据为空", id)
333			}
334			if u.ID != id {
335				return fmt.Errorf("用量标识不一致: 键 %q / 记录 %q", id, u.ID)
336			}
337			if u.ID == "" {
338				return errors.New("存在空的用量标识")
339			}
340			if _, ok := s.Customers[u.CustomerID]; !ok {
341				return fmt.Errorf("用量 %q 引用了不存在的客户 %q", u.ID, u.CustomerID)
342			}
343			if u.Quantity <= 0 {
344				return fmt.Errorf("用量 %q 的数量非正", u.ID)
345			}
346			if _, err := time.Parse(time.RFC3339, u.Time); err != nil {
347				return fmt.Errorf("用量 %q 的时间不是 RFC3339: %w", u.ID, err)
348			}
349		}
350		for key, b := range s.Bills {
351			if b == nil {
352				return fmt.Errorf("账单 %q 的数据为空", key)
353			}
354			if billKey(b.CustomerID, b.Month) != key {
355				return fmt.Errorf("账单键不一致: 键 %q / 客户月份 %s|%s", key, b.CustomerID, b.Month)
356			}
357			if _, ok := s.Customers[b.CustomerID]; !ok {
358				return fmt.Errorf("账单 %q 引用了不存在的客户 %q", key, b.CustomerID)
359			}
360			if !validMonth(b.Month) {
361				return fmt.Errorf("账单 %q 的月份无效", key)
362			}
363			if len(b.Lines) == 0 {
364				return fmt.Errorf("账单 %q 没有明细", key)
365			}
366			var qty, fee int64
367			for _, ln := range b.Lines {
368				u, ok := s.Usage[ln.UsageID]
369				if !ok {
370					return fmt.Errorf("账单 %q 引用了不存在的用量 %q", key, ln.UsageID)
371				}
372				if u.CustomerID != b.CustomerID || u.Time != ln.Time || u.Quantity != ln.Quantity {
373					return fmt.Errorf("账单 %q 的明细 %q 与用量记录不一致", key, ln.UsageID)
374				}
375				if !inMonth(u.Time, b.Month) {
376					return fmt.Errorf("账单 %q 的明细 %q 不在账期内", key, ln.UsageID)
377				}
378				var err error
379				qty, err = add64(qty, ln.Quantity)
380				if err != nil {
381					return fmt.Errorf("账单 %q 汇总数量溢出", key)
382				}
383				fee, err = add64(fee, ln.LineFee)
384				if err != nil {
385					return fmt.Errorf("账单 %q 汇总金额溢出", key)
386				}
387			}
388			if qty != b.TotalQty {
389				return fmt.Errorf("账单 %q 总数量与明细不符", key)
390			}
391			if fee != b.TotalFee {
392				return fmt.Errorf("账单 %q 总金额与明细不符", key)
393			}
394			c := s.Customers[b.CustomerID]
395			switch b.Pricing {
396			case "", "fixed":
397				// 固定单价账单：每条小计必须等于 数量×客户固定单价，且不得
398				// 携带阶梯方案信息或分段。
399				if b.PlanID != "" || b.PlanName != "" || len(b.PlanTiers) > 0 || len(b.TierTotals) > 0 {
400					return fmt.Errorf("账单 %q 是固定单价账单但携带阶梯方案信息", key)
401				}
402				for _, ln := range b.Lines {
403					if len(ln.Segments) > 0 {
404						return fmt.Errorf("账单 %q 的明细 %q 携带阶梯分段", key, ln.UsageID)
405					}
406					lf, err := mul64(ln.Quantity, c.Price)
407					if err != nil {
408						return fmt.Errorf("账单 %q 明细 %q 小计溢出", key, ln.UsageID)
409					}
410					if lf != ln.LineFee {
411						return fmt.Errorf("账单 %q 明细 %q 小计与数量×单价不符", key, ln.UsageID)
412					}
413				}
414				if b.UnitPrice != c.Price {
415					return fmt.Errorf("账单 %q 单价与客户固定单价不符", key)
416				}
417			case "tiered":
418				if err := s.validateTieredBill(key, b, c); err != nil {
419					return err
420				}
421			default:
422				return fmt.Errorf("账单 %q 的计价类型 %q 未知", key, b.Pricing)
423			}
424			// 封账期内不得存在游离于账单之外的用量（封账后新增被禁止，
425			// 而已入账记录理应全部在明细中）。
426			for _, u := range s.Usage {
427				if u.CustomerID == b.CustomerID && inMonth(u.Time, b.Month) {
428					found := false
429					for _, ln := range b.Lines {
430						if ln.UsageID == u.ID {
431							found = true
432							break
433						}
434					}
435					if !found {
436						return fmt.Errorf("客户 %s 的 %s 已封账，但用量 %q 未计入账单", b.CustomerID, b.Month, u.ID)
437					}
438				}
439			}
440		}
441	
442		// 调整与收款记录：标识、内容、引用与序号都必须自洽。
443		// 调整与收款共用同一个全局操作序号池；两者标识命名空间相互独立，
444		// 允许同名，各自判重与撤销。
445		if s.NextSeq < 0 {
446			return fmt.Errorf("操作序号计数器为负: %d", s.NextSeq)
447		}
448		seenSeq := make(map[int64]string) // 全局操作序号（登记与撤销共用同一池）-> 来源描述
449		for id, a := range s.Adjustments {
450			if a == nil {
451				return fmt.Errorf("调整 %q 的数据为空", id)
452			}
453			if a.ID != id {
454				return fmt.Errorf("调整标识不一致: 键 %q / 记录 %q", id, a.ID)
455			}
456			if a.ID == "" {
457				return errors.New("存在空的调整标识")
458			}
459			if a.Amount == 0 {
460				return fmt.Errorf("调整 %q 的金额为零", id)
461			}
462			if strings.TrimSpace(a.Reason) == "" {
463				return fmt.Errorf("调整 %q 的原因为空", id)
464			}
465			if !validMonth(a.Month) {
466				return fmt.Errorf("调整 %q 的月份无效", id)
467			}
468			if _, ok := s.Customers[a.CustomerID]; !ok {
469				return fmt.Errorf("调整 %q 引用了不存在的客户 %q", id, a.CustomerID)
470			}
471			if _, ok := s.Bills[billKey(a.CustomerID, a.Month)]; !ok {
472				return fmt.Errorf("调整 %q 引用了不存在的账单（客户 %s 月份 %s）", id, a.CustomerID, a.Month)
473			}
474			if a.Seq < 1 || a.Seq > s.NextSeq {
475				return fmt.Errorf("调整 %q 的操作序号越界", id)
476			}
477			if prev, dup := seenSeq[a.Seq]; dup {
478				return fmt.Errorf("调整 %q 与 %q 的操作序号重复", id, prev)
479			}
480			seenSeq[a.Seq] = "调整 " + id
481			if a.Revoked {
482				if strings.TrimSpace(a.RevokeReason) == "" {
483					return fmt.Errorf("调整 %q 已撤销但撤销原因为空", id)
484				}
485				if a.RevokeSeq <= a.Seq || a.RevokeSeq > s.NextSeq {
486					return fmt.Errorf("调整 %q 的撤销序号越界", id)
487				}
488				if prev, dup := seenSeq[a.RevokeSeq]; dup {
489					return fmt.Errorf("撤销调整 %q 与 %q 的操作序号重复", id, prev)
490				}
491				seenSeq[a.RevokeSeq] = "撤销调整 " + id
492			} else if a.RevokeReason != "" || a.RevokeSeq != 0 {
493				return fmt.Errorf("调整 %q 未撤销但存在撤销信息", id)
494			}
495		}
496		for id, p := range s.Payments {
497			if p == nil {
498				return fmt.Errorf("收款 %q 的数据为空", id)
499			}
500			if p.ID != id {
501				return fmt.Errorf("收款标识不一致: 键 %q / 记录 %q", id, p.ID)
502			}
503			if p.ID == "" {
504				return errors.New("存在空的收款标识")
505			}
506			if p.Total <= 0 {
507				return fmt.Errorf("收款 %q 的总额不是正整数", id)
508			}
509			if strings.TrimSpace(p.Note) == "" {
510				return fmt.Errorf("收款 %q 的备注为空", id)
511			}
512			if _, ok := s.Customers[p.CustomerID]; !ok {
513				return fmt.Errorf("收款 %q 引用了不存在的客户 %q", id, p.CustomerID)
514			}
515			if len(p.Allocations) == 0 {
516				return fmt.Errorf("收款 %q 没有分配", id)
517			}
518			seenMonths := make(map[string]bool)
519			var sum int64
520			for _, al := range p.Allocations {
521				if !validMonth(al.Month) {
522					return fmt.Errorf("收款 %q 的分配月份 %q 无效", id, al.Month)
523				}
524				if seenMonths[al.Month] {
525					return fmt.Errorf("收款 %q 的分配月份 %s 重复", id, al.Month)
526				}
527				seenMonths[al.Month] = true
528				if al.Amount <= 0 {
529					return fmt.Errorf("收款 %q 在 %s 的分配金额不是正整数", id, al.Month)
530				}
531				if _, ok := s.Bills[billKey(p.CustomerID, al.Month)]; !ok {
532					return fmt.Errorf("收款 %q 的分配引用了不存在的账单（客户 %s 月份 %s）", id, p.CustomerID, al.Month)
533				}
534				var err error
535				sum, err = add64(sum, al.Amount)
536				if err != nil {
537					return fmt.Errorf("收款 %q 的分配金额汇总溢出: %w", id, err)
538				}
539			}
540			if sum != p.Total {
541				return fmt.Errorf("收款 %q 的分配合计 %d 分与总额 %d 分不一致", id, sum, p.Total)
542			}
543			if p.Seq < 1 || p.Seq > s.NextSeq {
544				return fmt.Errorf("收款 %q 的操作序号越界", id)
545			}
546			if prev, dup := seenSeq[p.Seq]; dup {
547				return fmt.Errorf("收款 %q 与 %q 的操作序号重复", id, prev)
548			}
549			seenSeq[p.Seq] = "收款 " + id
550			if p.Revoked {
551				if strings.TrimSpace(p.RevokeReason) == "" {
552					return fmt.Errorf("收款 %q 已撤销但撤销原因为空", id)
553				}
554				if p.RevokeSeq <= p.Seq || p.RevokeSeq > s.NextSeq {
555					return fmt.Errorf("收款 %q 的撤销序号越界", id)
556				}
557				if prev, dup := seenSeq[p.RevokeSeq]; dup {
558					return fmt.Errorf("撤销收款 %q 与 %q 的操作序号重复", id, prev)
559				}
560				seenSeq[p.RevokeSeq] = "撤销收款 " + id
561			} else if p.RevokeReason != "" || p.RevokeSeq != 0 {
562				return fmt.Errorf("收款 %q 未撤销但存在撤销信息", id)
563			}
564		}
565		// 分配更正记录：标识、目标收款、原因、新分配与序号都必须自洽。
566		// 更正标识与收款、调整标识命名空间相互独立，允许同名。
567		for id, c := range s.Corrections {
568			if c == nil {
569				return fmt.Errorf("更正 %q 的数据为空", id)
570			}
571			if c.ID != id {
572				return fmt.Errorf("更正标识不一致: 键 %q / 记录 %q", id, c.ID)
573			}
574			if c.ID == "" {
575				return errors.New("存在空的更正标识")
576			}
577			p, ok := s.Payments[c.PaymentID]
578			if !ok {
579				return fmt.Errorf("更正 %q 引用了不存在的收款 %q", id, c.PaymentID)
580			}
581			if strings.TrimSpace(c.Reason) == "" {
582				return fmt.Errorf("更正 %q 的原因为空", id)
583			}
584			if len(c.Allocations) == 0 {
585				return fmt.Errorf("更正 %q 没有新分配", id)
586			}
587			seenMonths := make(map[string]bool)
588			var sum int64
589			for _, al := range c.Allocations {
590				if !validMonth(al.Month) {
591					return fmt.Errorf("更正 %q 的分配月份 %q 无效", id, al.Month)
592				}
593				if seenMonths[al.Month] {
594					return fmt.Errorf("更正 %q 的分配月份 %s 重复", id, al.Month)
595				}
596				seenMonths[al.Month] = true
597				if al.Amount <= 0 {
598					return fmt.Errorf("更正 %q 在 %s 的分配金额不是正整数", id, al.Month)
599				}
600				if _, ok := s.Bills[billKey(p.CustomerID, al.Month)]; !ok {
601					return fmt.Errorf("更正 %q 的分配引用了不存在的账单（客户 %s 月份 %s）", id, p.CustomerID, al.Month)
602				}
603				var err error
604				sum, err = add64(sum, al.Amount)
605				if err != nil {
606					return fmt.Errorf("更正 %q 的分配金额汇总溢出: %w", id, err)
607				}
608			}
609			if sum != p.Total {
610				return fmt.Errorf("更正 %q 的分配合计 %d 分与关联收款 %q 的总额 %d 分不一致", id, sum, c.PaymentID, p.Total)
611			}
612			if c.Seq <= p.Seq || c.Seq > s.NextSeq {
613				return fmt.Errorf("更正 %q 的操作序号越界", id)
614			}
615			if p.Revoked && c.Seq > p.RevokeSeq {
616				return fmt.Errorf("更正 %q 的操作序号晚于关联收款 %q 的撤销序号", id, c.PaymentID)
617			}
618			if prev, dup := seenSeq[c.Seq]; dup {
619				return fmt.Errorf("更正 %q 与 %q 的操作序号重复", id, prev)
620			}
621			seenSeq[c.Seq] = "更正 " + id
622		}
623		// 每张账单：当前应付（原总金额 + 全部未撤销调整净额）必须介于
624		// 0 与有符号 64 位最大值之间；实收（全部未撤销收款按最新分配在该月
625		// 计入之和）必须满足 0 ≤ 实收 ≤ 当前应付。越界说明金额与记录不一致。
626		for key, b := range s.Bills {
627			_, payable, err := billTotals(b, adjustmentsFor(s, b.CustomerID, b.Month))
628			if err != nil {
629				return fmt.Errorf("账单 %q 的调整金额与记录不一致: %w", key, err)
630			}
631			received, err := paymentReceived(s, b.CustomerID, b.Month)
632			if err != nil {
633				return fmt.Errorf("账单 %q 的收款金额与记录不一致: %w", key, err)
634			}
635			if received > payable {
636				return fmt.Errorf("账单 %q 的实收 %d 分超过当前应付 %d 分", key, received, payable)
637			}
638		}
639		return nil
640	}
