642	// validatePlanRules 校验阶梯方案的标识、名称与阶梯规则本身自洽：
643	// 至少一档，有限上限为严格递增的正整数，最后一档无上限，单价非负。
644	func validatePlanRules(p *plan) error {
645		if p.ID == "" || p.Name == "" {
646			return fmt.Errorf("方案 %q 的标识或名称为空", p.ID)
647		}
648		if len(p.Tiers) == 0 {
649			return fmt.Errorf("方案 %q 至少需要一档阶梯", p.ID)
650		}
651		prev := int64(0)
652		for i, t := range p.Tiers {
653			if t.Price < 0 {
654				return fmt.Errorf("方案 %q 第 %d 档单价为负", p.ID, i+1)
655			}
656			if i == len(p.Tiers)-1 {
657				if t.Limit != 0 {
658					return fmt.Errorf("方案 %q 最后一档必须无上限", p.ID)
659				}
660			} else {
661				if t.Limit <= 0 {
662					return fmt.Errorf("方案 %q 第 %d 档上限必须是正整数", p.ID, i+1)
663				}
664				if t.Limit <= prev {
665					return fmt.Errorf("方案 %q 的有限上限必须严格递增", p.ID)
666				}
667				prev = t.Limit
668			}
669		}
670		return nil
671	}
672	
673	// tiersEqual 判定两份阶梯规则完全相同。
674	func tiersEqual(a, b []tier) bool {
675		if len(a) != len(b) {
676			return false
677		}
678		for i := range a {
679			if a[i] != b[i] {
680				return false
681			}
682		}
683		return true
684	}
685	
686	// segmentsEqual 判定两份分段列表完全相同。
687	func segmentsEqual(a, b []lineSegment) bool {
688		if len(a) != len(b) {
689			return false
690		}
691		for i := range a {
692			if a[i] != b[i] {
693				return false
694			}
695		}
696		return true
697	}
698	
699	// sortedByInstant 判定用量记录是否按（解析后的时间点升序、同一时间按
700	// 标识字典序）排列，即阶梯计价的计价顺序。
701	func sortedByInstant(recs []*usageRecord) bool {
702		for i := 1; i < len(recs); i++ {
703			ti, _ := time.Parse(time.RFC3339, recs[i-1].Time)
704			tj, _ := time.Parse(time.RFC3339, recs[i].Time)
705			ui, uj := ti.UTC(), tj.UTC()
706			if uj.Before(ui) || (uj.Equal(ui) && recs[i].ID <= recs[i-1].ID) {
707				return false
708			}
709		}
710		return true
711	}
712	
713	// validateTieredBill 校验阶梯账单：方案引用有效、快照与方案一致、账单方案
714	// 符合账期月的方案安排，并按保存的方案规则从零累计重放计价，逐条比对分段、
715	// 小计、各档合计与总金额；任何不符都视为数据损坏。
716	func (s *state) validateTieredBill(key string, b *bill, c *customer) error {
717		if b.PlanID == "" {
718			return fmt.Errorf("账单 %q 缺少方案标识", key)
719		}
720		p, ok := s.Plans[b.PlanID]
721		if !ok {
722			return fmt.Errorf("账单 %q 引用了不存在的方案 %q", key, b.PlanID)
723		}
724		if b.PlanName != p.Name {
725			return fmt.Errorf("账单 %q 的方案名称快照与方案 %q 不符", key, b.PlanID)
726		}
727		if !tiersEqual(b.PlanTiers, p.Tiers) {
728			return fmt.Errorf("账单 %q 的方案规则快照与方案 %q 不符", key, b.PlanID)
729		}
730		// 账单方案必须符合账期安排：创建时绑定的初始方案被生效月不晚于
731		// 账期月的最后一次变更替换（无变更时即初始绑定，兼容旧存档）。
732		if want := s.effectivePlanID(c, b.Month); want != b.PlanID {
733			return fmt.Errorf("账单 %q 的方案 %q 与账期 %s 安排的方案 %q 不一致", key, b.PlanID, b.Month, want)
734		}
735		if b.UnitPrice != 0 {
736			return fmt.Errorf("账单 %q 是阶梯账单但保存了统一单价", key)
737		}
738		if len(b.TierTotals) != len(p.Tiers) {
739			return fmt.Errorf("账单 %q 的分档合计档数与方案规则不符", key)
740		}
741		// 明细必须按计价顺序排列（前面已逐条核验与用量记录一致）。
742		recs := make([]*usageRecord, len(b.Lines))
743		for i, ln := range b.Lines {
744			recs[i] = s.Usage[ln.UsageID]
745		}
746		if !sortedByInstant(recs) {
747			return fmt.Errorf("账单 %q 的明细未按计价顺序（时间点升序、同一时间按标识字典序）排列", key)
748		}
749		priced, err := tieredPrice(p.Tiers, recs)
750		if err != nil {
751			return fmt.Errorf("账单 %q 按方案规则计价失败: %w", key, err)
752		}
753		for i, ln := range b.Lines {
754			if !segmentsEqual(ln.Segments, priced.lines[i].segments) {
755				return fmt.Errorf("账单 %q 的明细 %q 分段与计价规则不符", key, ln.UsageID)
756			}
757			if ln.LineFee != priced.lines[i].fee {
758				return fmt.Errorf("账单 %q 的明细 %q 小计与计价规则不符", key, ln.UsageID)
759			}
760		}
761		for i, tt := range b.TierTotals {
762			if tt.Quantity != priced.tierQty[i] || tt.Fee != priced.tierFee[i] {
763				return fmt.Errorf("账单 %q 的第 %d 档合计与计价规则不符", key, i+1)
764			}
765		}
766		if b.TotalFee != priced.totalFee {
767			return fmt.Errorf("账单 %q 总金额与计价规则不符", key)
768		}
769		return nil
770	}
771	
772	// save 整体原子落盘：先写临时文件并同步，再 rename 覆盖。
773	// 只有完整保存成功后调用方才会向用户报告成功。
774	func (s *state) save() error {
775		if err := s.validate(); err != nil {
776			return fmt.Errorf("拒绝写入不一致的数据: %w", err)
777		}
778		data, err := json.MarshalIndent(s, "", "  ")
779		if err != nil {
780			return fmt.Errorf("序列化数据失败: %w", err)
781		}
782		data = append(data, '\n')
783	
784		tmp := s.path + ".tmp"
785		f, err := os.OpenFile(tmp, os.O_WRONLY|os.O_CREATE|os.O_TRUNC, 0o644)
786		if err != nil {
787			return fmt.Errorf("写入临时数据文件失败: %w", err)
788		}
789		if _, err := f.Write(data); err != nil {
790			f.Close()
791			os.Remove(tmp)
792			return fmt.Errorf("写入临时数据文件失败: %w", err)
793		}
794		if err := f.Sync(); err != nil {
795			f.Close()
796			os.Remove(tmp)
797			return fmt.Errorf("同步数据文件失败: %w", err)
798		}
799		if err := f.Close(); err != nil {
800			os.Remove(tmp)
801			return fmt.Errorf("关闭数据文件失败: %w", err)
802		}
803		if err := os.Rename(tmp, s.path); err != nil {
804			os.Remove(tmp)
805			return fmt.Errorf("替换数据文件失败: %w", err)
806		}
807		if dir, err := os.Open(filepath.Dir(s.path)); err == nil {
808			dir.Sync()
809			dir.Close()
810		}
811		return nil
812	}
813	
814	func billKey(customerID, month string) string {
815		return customerID + "|" + month
816	}
817	
818	func planChangeKey(customerID, month string) string {
819		return customerID + "|" + month
820	}
821	
822	// planChangesFor 返回某客户的全部方案变更，按生效月升序。
823	func (s *state) planChangesFor(customerID string) []*planChange {
824		var list []*planChange
825		for _, ch := range s.PlanChanges {
826			if ch.CustomerID == customerID {
827				list = append(list, ch)
828			}
829		}
830		sort.Slice(list, func(i, j int) bool { return list[i].Month < list[j].Month })
831		return list
832	}
833	
834	// effectivePlanID 返回客户在某 UTC 自然月实际适用的阶梯方案标识：
835	// 创建时绑定的初始方案，被生效月不晚于该月的最后一次变更替换。
836	func (s *state) effectivePlanID(cust *customer, month string) string {
837		planID := cust.PlanID
838		latest := ""
839		for _, ch := range s.PlanChanges {
840			if ch.CustomerID == cust.ID && ch.Month <= month && ch.Month >= latest {
841				latest = ch.Month
842				planID = ch.PlanID
843			}
844		}
845		return planID
846	}
847	
848	// sealed 报告某客户的指定月份是否已封账。
849	func (s *state) sealed(customerID, month string) bool {
850		_, ok := s.Bills[billKey(customerID, month)]
851		return ok
852	}
853	
854	// adjustmentsFor 返回某客户某月账单的全部调整，按操作序号升序。
855	func adjustmentsFor(s *state, customerID, month string) []*adjustment {
856		var list []*adjustment
857		for _, a := range s.Adjustments {
858			if a.CustomerID == customerID && a.Month == month {
859				list = append(list, a)
860			}
861		}
862		sort.Slice(list, func(i, j int) bool { return list[i].Seq < list[j].Seq })
863		return list
864	}
865	
866	// correctionsFor 返回某收款的全部分配更正，按操作序号升序。
867	func correctionsFor(s *state, paymentID string) []*correction {
868		var list []*correction
869		for _, c := range s.Corrections {
870			if c.PaymentID == paymentID {
871				list = append(list, c)
872			}
873		}
874		sort.Slice(list, func(i, j int) bool { return list[i].Seq < list[j].Seq })
875		return list
876	}
877	
878	// currentAllocations 返回一笔收款当前生效的分配：无更正时为首次登记的
879	// 原始分配，否则为序号最大（最新）的更正的分配。
880	func currentAllocations(s *state, p *payment) []paymentAllocation {
881		var latest *correction
882		for _, c := range s.Corrections {
883			if c.PaymentID == p.ID && (latest == nil || c.Seq > latest.Seq) {
884				latest = c
885			}
886		}
887		if latest != nil {
888			return latest.Allocations
889		}
890		return p.Allocations
891	}
892	
893	// allocAmountFor 返回分配列表中指定月份的金额；无该月分配时为 0。
894	func allocAmountFor(allocs []paymentAllocation, month string) int64 {
895		for _, al := range allocs {
896			if al.Month == month {
897				return al.Amount
898			}
899		}
900		return 0
901	}
902	
903	// paymentsEverFor 返回历史上曾涉及某客户某月账单的全部收款（首次登记
904	// 分配或任一次更正的新分配涉及该月，即使后来被更正移出），按操作序号升序。
905	func paymentsEverFor(s *state, customerID, month string) []*payment {
906		var list []*payment
907		for _, p := range s.Payments {
908			if p.CustomerID != customerID {
909				continue
910			}
911			involved := p.amountFor(month) > 0
912			if !involved {
913				for _, c := range s.Corrections {
914					if c.PaymentID == p.ID && allocAmountFor(c.Allocations, month) > 0 {
915						involved = true
916						break
917					}
918				}
919			}
920			if involved {
921				list = append(list, p)
922			}
923		}
924		sort.Slice(list, func(i, j int) bool { return list[i].Seq < list[j].Seq })
925		return list
926	}
927	
928	// paymentReceived 返回全部未撤销收款按最新分配在指定月份计入的实收之和。
929	// 各笔分配均为正整数，用非负 64 位加法累加，溢出时返回错误。
930	func paymentReceived(s *state, customerID, month string) (int64, error) {
931		var received int64
932		for _, p := range s.Payments {
933			if p.CustomerID != customerID || p.Revoked {
934				continue
935			}
936			amt := allocAmountFor(currentAllocations(s, p), month)
937			if amt <= 0 {
938				continue
939			}
940			var err error
941			received, err = add64(received, amt)
942			if err != nil {
943				return 0, err
944			}
945		}
946		return received, nil
947	}
948	
949	// errPayableOutOfRange 表示当前应付越出 [0, 有符号 64 位最大值]。
950	var errPayableOutOfRange = errors.New("当前应付越界（须介于 0 与有符号 64 位最大值之间）")
951	
952	// billTotals 计算全部未撤销调整的净额与当前应付（原总金额 + 净额）。
953	// 净额按 128 位精确求和（与顺序无关），再校验应付落在
954	// [0, 有符号 64 位最大值] 内，全程整数运算。
955	func billTotals(b *bill, adjs []*adjustment) (net, payable int64, err error) {
956		var amounts []int64
957		for _, a := range adjs {
958			if !a.Revoked {
959				amounts = append(amounts, a.Amount)
960			}
961		}
962		net, err = sumSigned64(amounts...)
963		if err != nil {
964			return 0, 0, err
965		}
966		payable, err = addSigned64(b.TotalFee, net)
967		if err != nil {
968			return 0, 0, err
969		}
970		if payable < 0 {
971			return 0, 0, errPayableOutOfRange
972		}
973		return net, payable, nil
974	}
975

