224		if file == "-" {
225			reader = io.NopCloser(os.Stdin)
226			source = "标准输入"
227		} else {
228			f, err := os.Open(file)
229			if err != nil {
230				return fmt.Errorf("无法打开用量文件 %s: %w", file, err)
231			}
232			reader = f
233			source = file
234		}
235		defer reader.Close()
236	
237		rows, parseErrs := parseUsageFile(reader)
238	
239		s, err := loadStore(dir)
240		if err != nil {
241			return err
242		}
243	
244		// 先校验：任何问题都在此阶段收集，全部通过后才一次性修改并保存，
245		// 保证“整批导入先校验再生效”，失败不留下任何新用量。
246		var problems []string
247		problems = append(problems, parseErrs...)
248	
249		accepted := make(map[string]*parsedRow) // 本批内首次出现、内容确定的记录
250		var ordered []*parsedRow
251		newCount, dupCount := 0, 0
252	
253		for _, r := range rows {
254			cust, ok := s.Customers[r.rec.CustomerID]
255			if !ok {
256				problems = append(problems, fmt.Sprintf("第 %d 行：客户标识 %q 不存在", r.line, r.rec.CustomerID))
257				continue
258			}
259			// 金额可行性预检：固定单价客户检查 数量×单价；阶梯客户按记录时间
260			// 换算的 UTC 月份的有效方案，以单条数量从零计价，检查分段金额不
261			// 溢出（金额单位：分）。
262			if cust.PlanID == "" {
263				if _, err := mul64(r.rec.Quantity, cust.Price); err != nil {
264					problems = append(problems, fmt.Sprintf("第 %d 行：数量 %d × 单价 %d 金额溢出有符号 64 位整数范围", r.line, r.rec.Quantity, cust.Price))
265					continue
266				}
267			} else {
268				rec := r.rec
269				month := r.t.UTC().Format("2006-01")
270				planID := s.effectivePlanID(cust, month)
271				if _, err := tieredPrice(s.Plans[planID].Tiers, []*usageRecord{&rec}); err != nil {
272					problems = append(problems, fmt.Sprintf("第 %d 行：按 %s 月有效方案 %q 对单条数量从零计价失败：%v", r.line, month, planID, err))
273					continue
274				}
275			}
276	
277			// 去重判定同时对“库中已有”和“本文件内已出现”生效。
278			var existing *usageRecord
279			if inStore, ok := s.Usage[r.rec.ID]; ok {
280				existing = inStore
281			} else if inBatch, ok := accepted[r.rec.ID]; ok {
282				existing = &inBatch.rec
283			}
284	
285			if existing != nil {
286				if !sameUsage(existing, &r.rec, r.t) {
287					problems = append(problems, fmt.Sprintf("第 %d 行：用量标识 %q 已存在但内容不同（已有客户=%s 时间=%s 数量=%d）",
288						r.line, r.rec.ID, existing.CustomerID, existing.Time, existing.Quantity))
289					continue
290				}
291				dupCount++
292				continue
293			}
294	
295			// 全新标识：不得进入该客户已封账的 UTC 自然月。
296			month := r.t.UTC().Format("2006-01")
297			if s.sealed(r.rec.CustomerID, month) {
298				problems = append(problems, fmt.Sprintf("第 %d 行：客户 %s 的 %s 已封账，新用量 %q 不得进入",
299					r.line, r.rec.CustomerID, month, r.rec.ID))
300				continue
301			}
302	
303			rr := r
304			accepted[r.rec.ID] = rr
305			ordered = append(ordered, rr)
306			newCount++
307		}
308	
309		if len(problems) > 0 {
310			return fmt.Errorf("导入失败，整批未生效（共 %d 个问题）：\n  %s", len(problems), strings.Join(problems, "\n  "))
311		}
312	
313		for _, r := range ordered {
314			rec := r.rec
315			s.Usage[rec.ID] = &rec
316		}
317		if err := s.save(); err != nil {
318			return err
319		}
320		fmt.Fprintf(stdout, "导入完成（%s）：新增 %d 条，重复跳过 %d 条\n", source, newCount, dupCount)
321		return nil
322	}
