324	// parseUsageFile 完整读取 CSV，做格式层面的解析；业务层面的校验在调用方完成。
325	func parseUsageFile(r io.Reader) ([]*parsedRow, []string) {
326		cr := csv.NewReader(r)
327		cr.FieldsPerRecord = 4
328		cr.TrimLeadingSpace = true
329	
330		header, err := cr.Read()
331		if err == io.EOF {
332			return nil, []string{"文件为空：首行必须是表头 " + usageHeader}
333		}
334		if err != nil {
335			return nil, []string{fmt.Sprintf("无法读取表头：%v（首行必须是 %s）", err, usageHeader)}
336		}
337		for i := range header {
338			header[i] = strings.TrimSpace(header[i])
339		}
340		if len(header) != 4 || header[0] != "usage_id" || header[1] != "customer_id" ||
341			header[2] != "time" || header[3] != "quantity" {
342			return nil, []string{fmt.Sprintf("表头必须是 %s，实际为 %s", usageHeader, strings.Join(header, ","))}
343		}
344	
345		var rows []*parsedRow
346		var problems []string
347		line := 1
348		for {
349			rec, err := cr.Read()
350			if err == io.EOF {
351				break
352			}
353			line++
354			if err != nil {
355				problems = append(problems, fmt.Sprintf("第 %d 行：CSV 格式错误：%v", line, err))
356				if pe, ok := err.(*csv.ParseError); ok && pe.Err == csv.ErrFieldCount {
357					// 字段数错误后继续读取仍可能拿到错乱记录，直接终止解析。
358					break
359				}
360				continue
361			}
362			for i := range rec {
363				rec[i] = strings.TrimSpace(rec[i])
364			}
365	
366			id, custID, ts, qtyText := rec[0], rec[1], rec[2], rec[3]
367			if id == "" {
368				problems = append(problems, fmt.Sprintf("第 %d 行：用量标识不能为空", line))
369				continue
370			}
371			if custID == "" {
372				problems = append(problems, fmt.Sprintf("第 %d 行：客户标识不能为空", line))
373				continue
374			}
375			t, err := time.Parse(time.RFC3339, ts)
376			if err != nil {
377				problems = append(problems, fmt.Sprintf("第 %d 行：时间 %q 不是 RFC3339 格式：%v", line, ts, err))
378				continue
379			}
380			qty, err := strconv.ParseInt(qtyText, 10, 64)
381			if err != nil {
382				problems = append(problems, fmt.Sprintf("第 %d 行：数量 %q 不是有符号 64 位整数", line, qtyText))
383				continue
384			}
385			if qty <= 0 {
386				problems = append(problems, fmt.Sprintf("第 %d 行：数量必须是正整数，收到 %d", line, qty))
387				continue
388			}
389	
390			rows = append(rows, &parsedRow{
391				line: line,
392				rec:  usageRecord{ID: id, CustomerID: custID, Time: ts, Quantity: qty},
393				t:    t,
394			})
395		}
396		return rows, problems
397	}
398	
399	// sameUsage 按（客户、解析后的时间点、数量）判定两条记录内容是否相同，
400	// 时间比较的是瞬间，因此 Z 与 +08:00 表示同一时刻视为相同。
401	func sameUsage(existing *usageRecord, candidate *usageRecord, candidateT time.Time) bool {
402		if existing.CustomerID != candidate.CustomerID || existing.Quantity != candidate.Quantity {
403			return false
404		}
405		et, err := time.Parse(time.RFC3339, existing.Time)
406		if err != nil {
407			return existing.Time == candidate.Time
408		}
409		return et.Equal(candidateT)
410	}
411	
412	// validMonth 严格校验 YYYY-MM（月份两位、01..12）。
413	func validMonth(m string) bool {
414		t, err := time.Parse("2006-01", m)
415		if err != nil || t.Format("2006-01") != m || t.Year() < 1 {
416			return false
417		}
418		return true
419	}
420	
421	// inMonth 判定一条 RFC3339 时间（换算 UTC 后）是否落在给定自然月。
422	func inMonth(rfc3339, month string) bool {
423		t, err := time.Parse(time.RFC3339, rfc3339)
424		if err != nil {
425			return false
426		}
427		return t.UTC().Format("2006-01") == month
428	}
429	
430	// utcMonth 返回 RFC3339 时间换算 UTC 后的自然月（YYYY-MM）。
431	// 入参时间均已在载入/导入时校验为 RFC3339。
432	func utcMonth(rfc3339 string) string {
433		t, _ := time.Parse(time.RFC3339, rfc3339)
434		return t.UTC().Format("2006-01")
435	}
