437	func cmdBillSettle(dir, customerID, month string) error {
438		if !validMonth(month) {
439			return fmt.Errorf("月份 %q 无效，必须是 YYYY-MM 形式（如 2026-09）", month)
440		}
441		s, err := loadStore(dir)
442		if err != nil {
443			return err
444		}
445		cust, ok := s.Customers[customerID]
446		if !ok {
447			return fmt.Errorf("客户标识 %q 不存在", customerID)
448		}
449	
450		key := billKey(customerID, month)
451		if existing, ok := s.Bills[key]; ok {
452			// 幂等：同一客户同一月份重复结算，直接返回原账单，
453			// 不重新计费、不产生新账单或调整、不落盘。
454			fmt.Fprintf(stdout, "客户 %s 的 %s 已结算，返回原账单（幂等，不重新计费）：\n\n", customerID, month)
455			printBill(existing, cust, s)
456			return nil
457		}
458	
459		// 归集该客户 UTC 自然月内的全部用量，区间为左闭右开 [月初, 下月初)。
460		inMonthRecs := monthUsage(s, customerID, month)
461		if len(inMonthRecs) == 0 {
462			return fmt.Errorf("客户 %s 在 %s 没有用量，拒绝结算且不封账", customerID, month)
463		}
464	
465		// 绑定阶梯方案的客户走按月累计分档计价；固定单价客户保持原路径。
466		if cust.PlanID != "" {
467			return settleTiered(s, cust, month, inMonthRecs)
468		}
469	
470		b, err := buildFixedBill(cust, month, inMonthRecs)
471		if err != nil {
472			return fmt.Errorf("%v，拒绝结算且不封账", err)
473		}
474		s.Bills[key] = b
475	
476		// 账单与封账状态在同一次原子保存中一起持久化；保存失败则一切不生效。
477		if err := s.save(); err != nil {
478			delete(s.Bills, key)
479			return err
480		}
481		fmt.Fprintf(stdout, "结算完成，客户 %s 的 %s 已封账：\n\n", customerID, month)
482		printBill(b, cust, s)
483		return nil
484	}
