506	// monthUsage 归集客户在某 UTC 自然月（左闭右开 [月初, 下月初)）内的全部
507	// 用量，并按计价顺序（解析后的时间点升序、同一时间按标识字典序）排列。
508	func monthUsage(s *state, customerID, month string) []*usageRecord {
509		var recs []*usageRecord
510		for _, u := range s.Usage {
511			if u.CustomerID == customerID && inMonth(u.Time, month) {
512				recs = append(recs, u)
513			}
514		}
515		sortByInstant(recs)
516		return recs
517	}
518	
519	// buildFixedBill 为固定单价客户构造账单（不落盘）：逐条 数量×单价 并汇总，
520	// 全程整数运算，任何一步溢出都返回错误。recs 须已按计价顺序排列。
521	func buildFixedBill(cust *customer, month string, recs []*usageRecord) (*bill, error) {
522		lines := make([]billLine, 0, len(recs))
523		var totalQty, totalFee int64
524		for _, u := range recs {
525			lineFee, err := mul64(u.Quantity, cust.Price)
526			if err != nil {
527				return nil, fmt.Errorf("用量 %s：数量 %d × 单价 %d 金额溢出", u.ID, u.Quantity, cust.Price)
528			}
529			if totalQty, err = add64(totalQty, u.Quantity); err != nil {
530				return nil, fmt.Errorf("汇总数量溢出有符号 64 位整数范围")
531			}
532			if totalFee, err = add64(totalFee, lineFee); err != nil {
533				return nil, fmt.Errorf("汇总金额溢出有符号 64 位整数范围")
534			}
535			lines = append(lines, billLine{
536				UsageID:  u.ID,
537				Time:     u.Time,
538				Quantity: u.Quantity,
539				LineFee:  lineFee,
540			})
541		}
542		return &bill{
543			ID:         stableBillID(cust.ID, month),
544			CustomerID: cust.ID,
545			Month:      month,
546			TotalQty:   totalQty,
547			UnitPrice:  cust.Price,
548			TotalFee:   totalFee,
549			Lines:      lines,
550			CreatedAt:  time.Now().UTC().Format(time.RFC3339),
551		}, nil
552	}
553	
554	func sortByInstant(us []*usageRecord) {
555		// 入参时间均已在载入/导入时校验为 RFC3339。
556		sort.Slice(us, func(i, j int) bool {
557			ti, _ := time.Parse(time.RFC3339, us[i].Time)
558			tj, _ := time.Parse(time.RFC3339, us[j].Time)
559			ui, uj := ti.UTC(), tj.UTC()
560			if !ui.Equal(uj) {
561				return ui.Before(uj)
562			}
563			return us[i].ID < us[j].ID
564		})
565	}
