573	func printBill(b *bill, cust *customer, s *state) {
574		adjs := adjustmentsFor(s, b.CustomerID, b.Month)
575		// 收款历史保留所有曾涉及本账单的收款：首次登记或任一次更正分配
576		// 涉及该月即纳入，即使后来被更正移出。
577		pays := paymentsEverFor(s, b.CustomerID, b.Month)
578		fmt.Fprintf(stdout, "账单标识：%s\n", b.ID)
579		fmt.Fprintf(stdout, "客户：%s（%s）\n", cust.ID, cust.Name)
580		fmt.Fprintf(stdout, "月份：%s（UTC 自然月，左闭右开）\n", b.Month)
581		tiered := b.Pricing == "tiered"
582		if tiered {
583			// 阶梯账单明确计价类型并展示方案与完整规则，不伪造统一单价。
584			fmt.Fprintf(stdout, "计价类型：阶梯计费（按 UTC 自然月累计用量分档计价，每月从零累计）\n")
585			fmt.Fprintf(stdout, "方案：%s（%s）\n", b.PlanID, b.PlanName)
586			fmt.Fprintln(stdout, "阶梯规则：")
587			for i, t := range b.PlanTiers {
588				if t.Limit == 0 {
589					fmt.Fprintf(stdout, "  第 %d 档：累计数量无上限，单价 %d 分（%s）\n", i+1, t.Price, moneyFen(t.Price))
590				} else {
591					fmt.Fprintf(stdout, "  第 %d 档：累计上限 %d，单价 %d 分（%s）\n", i+1, t.Limit, t.Price, moneyFen(t.Price))
592				}
593			}
594		} else {
595			fmt.Fprintf(stdout, "单价：%d 分（%s）\n", b.UnitPrice, moneyFen(b.UnitPrice))
596		}
597		fmt.Fprintf(stdout, "总数量：%d\n", b.TotalQty)
598		fmt.Fprintf(stdout, "总金额：%d 分（%s）\n", b.TotalFee, moneyFen(b.TotalFee))
599		if tiered {
600			fmt.Fprintln(stdout, "各档合计：")
601			for i, tt := range b.TierTotals {
602				fmt.Fprintf(stdout, "  第 %d 档：数量 %d，单价 %d 分，金额 %d 分（%s）\n",
603					i+1, tt.Quantity, b.PlanTiers[i].Price, tt.Fee, moneyFen(tt.Fee))
604			}
605		}
606		// 数据在载入时已校验一致，此处计算不会出错。
607		net, payable, _ := billTotals(b, adjs)
608		received, _ := paymentReceived(s, b.CustomerID, b.Month)
609		outstanding := payable - received // 不变量保证 0 ≤ 实收 ≤ 当前应付
610		fmt.Fprintf(stdout, "调整净额：%+d 分（%s）\n", net, moneyFen(net))
611		fmt.Fprintf(stdout, "当前应付：%d 分（%s）\n", payable, moneyFen(payable))
612		fmt.Fprintf(stdout, "实收：%d 分（%s）\n", received, moneyFen(received))
613		fmt.Fprintf(stdout, "未收余额：%d 分（%s）\n", outstanding, moneyFen(outstanding))
614		fmt.Fprintln(stdout, "明细：")
615		for i, ln := range b.Lines {
616			fmt.Fprintf(stdout, "  %d. 用量标识=%s 时间=%s 数量=%d 小计=%d 分（%s）\n",
617				i+1, ln.UsageID, ln.Time, ln.Quantity, ln.LineFee, moneyFen(ln.LineFee))
618			// 阶梯账单逐条展示跨档分段的数量、单价与小计。
619			for j, seg := range ln.Segments {
620				fmt.Fprintf(stdout, "     分段 %d：第 %d 档 数量=%d 单价=%d 分 小计=%d 分（%s）\n",
621					j+1, seg.Tier+1, seg.Quantity, b.PlanTiers[seg.Tier].Price, seg.Fee, moneyFen(seg.Fee))
622			}
623		}
624		if len(adjs) == 0 {
625			fmt.Fprintln(stdout, "调整与撤销历史：无")
626		} else {
627			fmt.Fprintln(stdout, "调整与撤销历史（按成功操作顺序）：")
628			for i, ev := range historyEvents(adjs) {
629				fmt.Fprintf(stdout, "  %d. %s\n", i+1, ev)
630			}
631		}
632		if len(pays) == 0 {
633			fmt.Fprintln(stdout, "收款与撤销历史：无")
634		} else {
635			fmt.Fprintln(stdout, "收款与撤销历史（按成功操作顺序）：")
636			for i, ev := range paymentHistoryEvents(s, pays, b.Month) {
637				fmt.Fprintf(stdout, "  %d. %s\n", i+1, ev)
638			}
639		}
640	}
