642	// historyEvents 把调整与撤销展开为按操作序号排序的可读历史条目。
643	func historyEvents(adjs []*adjustment) []string {
644		type event struct {
645			seq  int64
646			text string
647		}
648		var events []event
649		for _, a := range adjs {
650			events = append(events, event{a.Seq, fmt.Sprintf("调整 %s：%s %+d 分（%s），原因：%s，当前状态：%s",
651				a.ID, adjustKind(a.Amount), a.Amount, moneyFen(a.Amount), a.Reason, adjustStatus(a))})
652			if a.Revoked {
653				events = append(events, event{a.RevokeSeq, fmt.Sprintf("撤销 %s：原因：%s（关联调整 %s 的%s %+d 分）",
654					a.ID, a.RevokeReason, a.ID, adjustKind(a.Amount), a.Amount)})
655			}
656		}
657		sort.Slice(events, func(i, j int) bool { return events[i].seq < events[j].seq })
658		out := make([]string, len(events))
659		for i, ev := range events {
660			out[i] = ev.text
661		}
662		return out
663	}
664	
665	func adjustKind(amount int64) string {
666		if amount > 0 {
667			return "补收"
668		}
669		return "减免"
670	}
671	
672	func adjustStatus(a *adjustment) string {
673		if a.Revoked {
674			return "已撤销"
675		}
676		return "生效中"
677	}
678	
679	// paymentHistoryEvents 把收款登记、分配更正与撤销展开为按操作序号排序的
680	// 可读历史条目；month 为当前展示账单所在月份。收款事件展示首次登记时在
681	// 本账单的分配，更正事件展示本账单分配的前后变化，撤销事件展示被整笔取消
682	// 的最新分配。
683	func paymentHistoryEvents(s *state, pays []*payment, month string) []string {
684		type event struct {
685			seq  int64
686			text string
687		}
688		var events []event
689		for _, p := range pays {
690			alloc := p.amountFor(month)
691			events = append(events, event{p.Seq, fmt.Sprintf("收款 %s：总额 %d 分（%s），本账单分配 %d 分（%s），备注：%s，当前状态：%s（客户 %s）",
692				p.ID, p.Total, moneyFen(p.Total), alloc, moneyFen(alloc), p.Note, paymentStatus(p), p.CustomerID)})
693			// 以首次登记分配为起点，按序号回放该收款在本账单的分配变化。
694			running := alloc
695			for _, c := range correctionsFor(s, p.ID) {
696				after := allocAmountFor(c.Allocations, month)
697				if running == 0 && after == 0 {
698					continue // 本次更正不涉及本账单
699				}
700				events = append(events, event{c.Seq, fmt.Sprintf("更正 %s：原因：%s（关联收款 %s，本账单分配 %d 分 → %d 分）",
701					c.ID, c.Reason, p.ID, running, after)})
702				running = after
703			}
704			if p.Revoked {
705				// 整笔撤销取消的是撤销时的最新分配。
706				events = append(events, event{p.RevokeSeq, fmt.Sprintf("撤销收款 %s：原因：%s（关联收款 %s，总额 %d 分，本账单分配 %d 分）",
707					p.ID, p.RevokeReason, p.ID, p.Total, running)})
708			}
709		}
710		sort.Slice(events, func(i, j int) bool { return events[i].seq < events[j].seq })
711		out := make([]string, len(events))
712		for i, ev := range events {
713			out[i] = ev.text
714		}
715		return out
716	}
