725	// parseAmount 解析调整金额：有符号 64 位整数、非零（正数补收、负数减免）。
726	func parseAmount(text string) (int64, error) {
727		text = strings.TrimSpace(text)
728		amount, err := strconv.ParseInt(text, 10, 64)
729		if err != nil {
730			return 0, fmt.Errorf("调整金额 %q 不是有符号 64 位整数范围内的整数: %w", text, err)
731		}
732		if amount == 0 {
733			return 0, fmt.Errorf("调整金额不能为零分（正数补收、负数减免）")
734		}
735		return amount, nil
736	}
