738	func cmdBillAdjust(dir, customerID, month, adjID, amountText, reason string) error {
739		if !validMonth(month) {
740			return fmt.Errorf("月份 %q 无效，必须是 YYYY-MM 形式（如 2026-09）", month)
741		}
742		if strings.TrimSpace(adjID) == "" {
743			return fmt.Errorf("调整标识不能为空")
744		}
745		amount, err := parseAmount(amountText)
746		if err != nil {
747			return err
748		}
749		if strings.TrimSpace(reason) == "" {
750			return fmt.Errorf("调整原因不能为空")
751		}
752	
753		s, err := loadStore(dir)
754		if err != nil {
755			return err
756		}
757		if _, ok := s.Customers[customerID]; !ok {
758			return fmt.Errorf("客户标识 %q 不存在", customerID)
759		}
760		b, ok := s.Bills[billKey(customerID, month)]
761		if !ok {
762			return fmt.Errorf("客户 %s 的 %s 尚无账单（未结算），费用调整只能作用于已存在账单", customerID, month)
763		}
764	
765		if existing, ok := s.Adjustments[adjID]; ok {
766			// 相同标识按客户、月份、金额、原因判断重复：内容相同返回已保存
767			// 记录，不再次增减应付；已撤销的重放仍返回已撤销状态，不重新生效。
768			if existing.CustomerID == customerID && existing.Month == month &&
769				existing.Amount == amount && existing.Reason == reason {
770				fmt.Fprintf(stdout, "调整 %q 已存在且内容相同，返回已保存记录（不重复增减应付）：\n\n", adjID)
771				printAdjustment(existing, s)
772				return nil
773			}
774			return fmt.Errorf("调整标识 %q 已存在但内容不同（已有：客户=%s 月份=%s 金额=%d 原因=%q），拒绝复用",
775				adjID, existing.CustomerID, existing.Month, existing.Amount, existing.Reason)
776		}
777	
778		// 应付可行性预检：原总金额 + 全部未撤销调整 + 本次金额必须落在
779		// [0, 有符号 64 位最大值] 内，且不得低于已登记实收，否则拒绝且
780		// 不占用该调整标识。
781		_, payable, err := billTotals(b, adjustmentsFor(s, customerID, month))
782		if err != nil {
783			return fmt.Errorf("账单当前应付异常，拒绝调整: %w", err)
784		}
785		received, err := paymentReceived(s, customerID, month)
786		if err != nil {
787			return fmt.Errorf("实收累计异常，拒绝调整: %w", err)
788		}
789		newPayable, err := addSigned64(payable, amount)
790		if err != nil {
791			return fmt.Errorf("调整后当前应付超出有符号 64 位最大值（当前 %d 分，本次 %+d 分），拒绝调整", payable, amount)
792		}
793		if newPayable < 0 {
794			return fmt.Errorf("调整后当前应付将为 %d 分（小于 0，当前 %d 分，本次 %+d 分），拒绝调整", newPayable, payable, amount)
795		}
796		if newPayable < received {
797			return fmt.Errorf("调整后当前应付 %d 分将低于实收 %d 分（当前 %d 分，本次 %+d 分），拒绝调整；可先撤销误登记的收款再重试",
798				newPayable, received, payable, amount)
799		}
800	
801		a := &adjustment{
802			ID:         adjID,
803			CustomerID: customerID,
804			Month:      month,
805			Amount:     amount,
806			Reason:     reason,
807			CreatedAt:  time.Now().UTC().Format(time.RFC3339),
808		}
809		s.NextSeq++
810		a.Seq = s.NextSeq
811		s.Adjustments[adjID] = a
812	
813		// 调整记录与序号在同一次原子保存中持久化；保存失败则一切不生效，
814		// 该调整标识不被占用。
815		if err := s.save(); err != nil {
816			delete(s.Adjustments, adjID)
817			s.NextSeq--
818			return err
819		}
820		fmt.Fprintf(stdout, "已登记%s调整 %q，客户 %s 的 %s 当前应付 %d 分（%s）：\n\n",
821			adjustKind(amount), adjID, customerID, month, newPayable, moneyFen(newPayable))
822		printAdjustment(a, s)
823		return nil
824	}
