826	func cmdBillRevoke(dir, adjID, reason string) error {
827		if strings.TrimSpace(adjID) == "" {
828			return fmt.Errorf("调整标识不能为空")
829		}
830		if strings.TrimSpace(reason) == "" {
831			return fmt.Errorf("撤销原因不能为空")
832		}
833	
834		s, err := loadStore(dir)
835		if err != nil {
836			return err
837		}
838		a, ok := s.Adjustments[adjID]
839		if !ok {
840			return fmt.Errorf("调整标识 %q 不存在，无法撤销", adjID)
841		}
842	
843		if a.Revoked {
844			// 相同标识与相同原因重复撤销：幂等成功，不新增记录；
845			// 改用其他原因则拒绝。
846			if a.RevokeReason == reason {
847				fmt.Fprintf(stdout, "调整 %q 已撤销且撤销原因相同，幂等返回（不新增记录）：\n\n", adjID)
848				printAdjustment(a, s)
849				return nil
850			}
851			return fmt.Errorf("调整 %q 已撤销（撤销原因 %q），改用其他原因重复撤销被拒绝", adjID, a.RevokeReason)
852		}
853	
854		// 撤销只取消该笔调整的金额影响；若撤销后当前应付越界或低于实收则
855		// 拒绝，该调整仍保持有效，可先撤销误登记的收款或在其他合法调整
856		// 改变余额后重试。
857		b := s.Bills[billKey(a.CustomerID, a.Month)] // 载入时已校验存在
858		_, payable, err := billTotals(b, adjustmentsFor(s, a.CustomerID, a.Month))
859		if err != nil {
860			return fmt.Errorf("账单当前应付异常，拒绝撤销: %w", err)
861		}
862		received, err := paymentReceived(s, a.CustomerID, a.Month)
863		if err != nil {
864			return fmt.Errorf("实收累计异常，拒绝撤销: %w", err)
865		}
866		neg, err := neg64(a.Amount)
867		if err != nil {
868			return fmt.Errorf("撤销后当前应付将超出有符号 64 位最大值，拒绝撤销；该调整仍有效，可在其他合法调整改变余额后重试")
869		}
870		newPayable, err := addSigned64(payable, neg)
871		if err != nil {
872			return fmt.Errorf("撤销后当前应付将超出有符号 64 位最大值（当前 %d 分，取消 %+d 分），拒绝撤销；该调整仍有效，可在其他合法调整改变余额后重试",
873				payable, a.Amount)
874		}
875		if newPayable < 0 {
876			return fmt.Errorf("撤销后当前应付将为 %d 分（小于 0，当前 %d 分，取消 %+d 分），拒绝撤销；该调整仍有效，可在其他合法调整改变余额后重试",
877				newPayable, payable, a.Amount)
878		}
879		if newPayable < received {
880			return fmt.Errorf("撤销后当前应付 %d 分将低于实收 %d 分（当前 %d 分，取消 %+d 分），拒绝撤销；可先撤销误登记的收款再重试",
881				newPayable, received, payable, a.Amount)
882		}
883	
884		a.Revoked = true
885		a.RevokeReason = reason
886		a.RevokedAt = time.Now().UTC().Format(time.RFC3339)
887		s.NextSeq++
888		a.RevokeSeq = s.NextSeq
889	
890		// 撤销信息与原记录在同一次原子保存中持久化；保存失败则一切不生效。
891		if err := s.save(); err != nil {
892			a.Revoked = false
893			a.RevokeReason = ""
894			a.RevokedAt = ""
895			a.RevokeSeq = 0
896			s.NextSeq--
897			return err
898		}
899		fmt.Fprintf(stdout, "已撤销调整 %q（%s %+d 分），客户 %s 的 %s 当前应付 %d 分（%s）：\n\n",
900			adjID, adjustKind(a.Amount), a.Amount, a.CustomerID, a.Month, newPayable, moneyFen(newPayable))
901		printAdjustment(a, s)
902		return nil
903	}
