905	// printAdjustment 输出单笔调整记录及其当前状态；payable 取自当前库状态。
906	func printAdjustment(a *adjustment, s *state) {
907		b := s.Bills[billKey(a.CustomerID, a.Month)]
908		_, payable, _ := billTotals(b, adjustmentsFor(s, a.CustomerID, a.Month))
909		fmt.Fprintf(stdout, "调整标识：%s\n", a.ID)
910		fmt.Fprintf(stdout, "客户：%s\n", a.CustomerID)
911		fmt.Fprintf(stdout, "月份：%s\n", a.Month)
912		fmt.Fprintf(stdout, "调整金额：%+d 分（%s，%s）\n", a.Amount, moneyFen(a.Amount), adjustKind(a.Amount))
913		fmt.Fprintf(stdout, "原因：%s\n", a.Reason)
914		if a.Revoked {
915			fmt.Fprintf(stdout, "当前状态：已撤销（撤销原因：%s）\n", a.RevokeReason)
916		} else {
917			fmt.Fprintf(stdout, "当前状态：生效中\n")
918		}
919		fmt.Fprintf(stdout, "当前应付：%d 分（%s）\n", payable, moneyFen(payable))
920	}
