922	// parsePositiveAmount 解析收款金额：正整数分（不接受零、负数、小数）。
923	func parsePositiveAmount(text string) (int64, error) {
924		text = strings.TrimSpace(text)
925		amount, err := strconv.ParseInt(text, 10, 64)
926		if err != nil {
927			return 0, fmt.Errorf("收款金额 %q 不是有符号 64 位整数范围内的整数: %w", text, err)
928		}
929		if amount <= 0 {
930			return 0, fmt.Errorf("收款金额必须是正整数分，收到 %d", amount)
931		}
932		return amount, nil
933	}
