935	func cmdBillPay(dir, customerID, month, payID, amountText, note string) error {
936		if !validMonth(month) {
937			return fmt.Errorf("月份 %q 无效，必须是 YYYY-MM 形式（如 2026-09）", month)
938		}
939		amount, err := parsePositiveAmount(amountText)
940		if err != nil {
941			return err
942		}
943		// 单账单收款视为只有一项分配的汇款，与 bill remit 共用同一核心。
944		return registerPayment(dir, customerID, payID, amount, note,
945			[]paymentAllocation{{Month: month, Amount: amount}})
946	}
