948	func cmdBillRemit(dir, customerID, payID, totalText, note string, allocArgs []string) error {
949		total, err := parsePositiveAmount(totalText)
950		if err != nil {
951			return err
952		}
953		allocs, err := parseAllocations(allocArgs)
954		if err != nil {
955			return err
956		}
957		// 分配合计必须等于总额，全程整数运算，溢出拒绝。
958		var sum int64
959		for _, al := range allocs {
960			sum, err = add64(sum, al.Amount)
961			if err != nil {
962				return fmt.Errorf("分配金额合计溢出有符号 64 位整数范围，拒绝登记")
963			}
964		}
965		if sum != total {
966			return fmt.Errorf("分配合计 %d 分与收款总额 %d 分不一致，拒绝登记", sum, total)
967		}
968		return registerPayment(dir, customerID, payID, total, note, allocs)
969	}
