971	// parseAllocations 解析 <YYYY-MM:金额分> 形式的分配列表：至少一项，
972	// 月份不得重复，每项金额为正整数分。
973	func parseAllocations(args []string) ([]paymentAllocation, error) {
974		if len(args) == 0 {
975			return nil, fmt.Errorf("分配列表不能为空，至少需要一项 <YYYY-MM:金额分>")
976		}
977		seen := make(map[string]bool)
978		allocs := make([]paymentAllocation, 0, len(args))
979		for _, arg := range args {
980			parts := strings.Split(arg, ":")
981			if len(parts) != 2 {
982				return nil, fmt.Errorf("分配项 %q 格式非法，应为 YYYY-MM:金额分（如 2026-09:500）", arg)
983			}
984			month := strings.TrimSpace(parts[0])
985			if !validMonth(month) {
986				return nil, fmt.Errorf("分配项 %q 的月份 %q 无效，必须是 YYYY-MM 形式（如 2026-09）", arg, parts[0])
987			}
988			if seen[month] {
989				return nil, fmt.Errorf("分配月份 %s 重复，拒绝登记", month)
990			}
991			seen[month] = true
992			amount, err := parsePositiveAmount(parts[1])
993			if err != nil {
994				return nil, fmt.Errorf("分配项 %q 的金额无效: %w", arg, err)
995			}
996			allocs = append(allocs, paymentAllocation{Month: month, Amount: amount})
997		}
998		return allocs, nil
999	}
