1001	// registerPayment 是 bill pay 与 bill remit 共用的收款登记核心：
1002	// 先整体校验再整笔生效，任何一项不合法都不落盘、不占用收款标识。
1003	func registerPayment(dir, customerID, payID string, total int64, note string, allocs []paymentAllocation) error {
1004		if strings.TrimSpace(payID) == "" {
1005			return fmt.Errorf("收款标识不能为空")
1006		}
1007		if strings.TrimSpace(note) == "" {
1008			return fmt.Errorf("收款备注不能为空")
1009		}
1010		// 分配顺序不影响收款身份：统一按月份升序保存与比较。
1011		sort.Slice(allocs, func(i, j int) bool { return allocs[i].Month < allocs[j].Month })
1012	
1013		s, err := loadStore(dir)
1014		if err != nil {
1015			return err
1016		}
1017		if _, ok := s.Customers[customerID]; !ok {
1018			return fmt.Errorf("客户标识 %q 不存在", customerID)
1019		}
1020		for _, al := range allocs {
1021			if _, ok := s.Bills[billKey(customerID, al.Month)]; !ok {
1022				return fmt.Errorf("客户 %s 的 %s 尚无账单（未结算），收款只能登记到已存在账单", customerID, al.Month)
1023			}
1024		}
1025	
1026		if existing, ok := s.Payments[payID]; ok {
1027			// 相同标识按客户、总额、备注与月份-金额对应关系判断重复：内容相同
1028			// 返回已保存记录，不再次计入实收，也不受当前余额变化影响；
1029			// 已撤销的重放仍返回已撤销状态，不恢复实收。
1030			if samePaymentContent(existing, customerID, total, note, allocs) {
1031				fmt.Fprintf(stdout, "收款 %q 已存在且内容相同，返回已保存记录（不重复计入实收）：\n\n", payID)
1032				printPayment(existing, s)
1033				return nil
1034			}
1035			return fmt.Errorf("收款标识 %q 已存在但内容不同（已有：客户=%s 总额=%d 备注=%q 分配=%s），拒绝复用",
1036				payID, existing.CustomerID, existing.Total, existing.Note, formatAllocations(existing.Allocations))
1037		}
1038	
1039		// 首次登记：每项分配不得超过对应账单的未收余额，全部合法才整笔生效。
1040		for _, al := range allocs {
1041			b := s.Bills[billKey(customerID, al.Month)]
1042			_, payable, err := billTotals(b, adjustmentsFor(s, customerID, al.Month))
1043			if err != nil {
1044				return fmt.Errorf("客户 %s 的 %s 当前应付异常，拒绝登记收款: %w", customerID, al.Month, err)
1045			}
1046			received, err := paymentReceived(s, customerID, al.Month)
1047			if err != nil {
1048				return fmt.Errorf("客户 %s 的 %s 实收累计溢出有符号 64 位整数范围，拒绝登记收款: %w", customerID, al.Month, err)
1049			}
1050			if payable == 0 {
1051				return fmt.Errorf("客户 %s 的 %s 当前应付为 0 分，不能登记正额收款", customerID, al.Month)
1052			}
1053			if al.Amount > payable-received {
1054				return fmt.Errorf("分配 %d 分超过未收余额 %d 分（客户 %s 的 %s：当前应付 %d 分，实收 %d 分），拒绝登记",
1055					al.Amount, payable-received, customerID, al.Month, payable, received)
1056			}
1057		}
1058	
1059		p := &payment{
1060			ID:          payID,
1061			CustomerID:  customerID,
1062			Total:       total,
1063			Note:        note,
1064			Allocations: allocs,
1065			CreatedAt:   time.Now().UTC().Format(time.RFC3339),
1066		}
1067		s.NextSeq++
1068		p.Seq = s.NextSeq
1069		s.Payments[payID] = p
1070	
1071		// 收款记录、序号与余额状态在同一次原子保存中持久化；保存失败则
1072		// 一切不生效，该收款标识不被占用。
1073		if err := s.save(); err != nil {
1074			delete(s.Payments, payID)
1075			s.NextSeq--
1076			return err
1077		}
1078		fmt.Fprintf(stdout, "已登记收款 %q（总额 %d 分，%s）：\n", payID, total, moneyFen(total))
1079		printAllocationBalances(s, p, allocs)
1080		fmt.Fprintln(stdout)
1081		printPayment(p, s)
1082		return nil
1083	}
