1094	// sameAllocations 判定两个分配列表的月份-金额对应关系相同（顺序无关）。
1095	func sameAllocations(a, b []paymentAllocation) bool {
1096		if len(a) != len(b) {
1097			return false
1098		}
1099		for _, al := range b {
1100			if allocAmountFor(a, al.Month) != al.Amount {
1101				return false
1102			}
1103		}
1104		return true
1105	}
