1107	// formatAllocations 以 "2026-09:500,2026-10:300" 形式展示分配列表。
1108	func formatAllocations(allocs []paymentAllocation) string {
1109		parts := make([]string, len(allocs))
1110		for i, al := range allocs {
1111			parts[i] = fmt.Sprintf("%s:%d", al.Month, al.Amount)
1112		}
1113		return strings.Join(parts, ",")
1114	}
