1127	func cmdBillUnpay(dir, payID, reason string) error {
1128		if strings.TrimSpace(payID) == "" {
1129			return fmt.Errorf("收款标识不能为空")
1130		}
1131		if strings.TrimSpace(reason) == "" {
1132			return fmt.Errorf("撤销原因不能为空")
1133		}
1134	
1135		s, err := loadStore(dir)
1136		if err != nil {
1137			return err
1138		}
1139		p, ok := s.Payments[payID]
1140		if !ok {
1141			return fmt.Errorf("收款标识 %q 不存在，无法撤销", payID)
1142		}
1143	
1144		if p.Revoked {
1145			// 相同标识与相同原因重复撤销：幂等成功，不新增历史；
1146			// 改用其他原因则拒绝。
1147			if p.RevokeReason == reason {
1148				fmt.Fprintf(stdout, "收款 %q 已撤销且撤销原因相同，幂等返回（不新增历史）：\n\n", payID)
1149				printPayment(p, s)
1150				return nil
1151			}
1152			return fmt.Errorf("收款 %q 已撤销（撤销原因 %q），改用其他原因重复撤销被拒绝", payID, p.RevokeReason)
1153		}
1154	
1155		// 撤销整笔生效：取消该笔在全部分配月份上的最新实收（经更正的以最新
1156		// 分配为准），不接受部分撤销；不改变应付、其他收款或调整，原收款、
1157		// 分配、更正与撤销原因永久保留。
1158		p.Revoked = true
1159		p.RevokeReason = reason
1160		p.RevokedAt = time.Now().UTC().Format(time.RFC3339)
1161		s.NextSeq++
1162		p.RevokeSeq = s.NextSeq
1163	
1164		// 撤销信息与原记录在同一次原子保存中持久化；保存失败则一切不生效。
1165		if err := s.save(); err != nil {
1166			p.Revoked = false
1167			p.RevokeReason = ""
1168			p.RevokedAt = ""
1169			p.RevokeSeq = 0
1170			s.NextSeq--
1171			return err
1172		}
1173		fmt.Fprintf(stdout, "已撤销收款 %q（总额 %d 分，%s），取消最新分配：\n", payID, p.Total, moneyFen(p.Total))
1174		printAllocationBalances(s, p, currentAllocations(s, p))
1175		fmt.Fprintln(stdout)
1176		printPayment(p, s)
1177		return nil
1178	}
