1180	// printPayment 输出单笔收款记录：总额、首次登记的全部分配（永久保留，
1181	// 判重依据）与当前状态；经历过更正时同时展示当前生效的最新分配。
1182	// 各月应付/实收取自当前库状态。
1183	func printPayment(p *payment, s *state) {
1184		fmt.Fprintf(stdout, "收款标识：%s\n", p.ID)
1185		fmt.Fprintf(stdout, "客户：%s\n", p.CustomerID)
1186		fmt.Fprintf(stdout, "收款总额：%d 分（%s）\n", p.Total, moneyFen(p.Total))
1187		fmt.Fprintf(stdout, "备注：%s\n", p.Note)
1188		if p.Revoked {
1189			fmt.Fprintf(stdout, "当前状态：已撤销（撤销原因：%s）\n", p.RevokeReason)
1190		} else {
1191			fmt.Fprintf(stdout, "当前状态：实收中\n")
1192		}
1193		fmt.Fprintln(stdout, "分配明细（首次登记，永久保留）：")
1194		for i, al := range p.Allocations {
1195			b := s.Bills[billKey(p.CustomerID, al.Month)] // 载入时已校验存在
1196			_, payable, _ := billTotals(b, adjustmentsFor(s, p.CustomerID, al.Month))
1197			received, _ := paymentReceived(s, p.CustomerID, al.Month)
1198			fmt.Fprintf(stdout, "  %d. 月份 %s：分配 %d 分（%s）；当前应付 %d 分，实收合计 %d 分，未收余额 %d 分\n",
1199				i+1, al.Month, al.Amount, moneyFen(al.Amount), payable, received, payable-received)
1200		}
1201		if corrs := correctionsFor(s, p.ID); len(corrs) > 0 {
1202			fmt.Fprintf(stdout, "当前分配（经 %d 次更正，以最新为准）：%s\n",
1203				len(corrs), formatAllocations(currentAllocations(s, p)))
1204		}
1205	}
