1207	// --- 收款分配更正 ---
1208	
1209	func cmdBillCorrect(dir, payID, corrID, reason string, allocArgs []string) error {
1210		if strings.TrimSpace(payID) == "" {
1211			return fmt.Errorf("收款标识不能为空")
1212		}
1213		if strings.TrimSpace(corrID) == "" {
1214			return fmt.Errorf("更正标识不能为空")
1215		}
1216		if strings.TrimSpace(reason) == "" {
1217			return fmt.Errorf("更正原因不能为空")
1218		}
1219		allocs, err := parseAllocations(allocArgs)
1220		if err != nil {
1221			return err
1222		}
1223		// 分配顺序不影响更正身份：统一按月份升序保存与比较。
1224		sort.Slice(allocs, func(i, j int) bool { return allocs[i].Month < allocs[j].Month })
1225	
1226		s, err := loadStore(dir)
1227		if err != nil {
1228			return err
1229		}
1230		p, ok := s.Payments[payID]
1231		if !ok {
1232			return fmt.Errorf("收款标识 %q 不存在，无法更正分配", payID)
1233		}
1234	
1235		if existing, ok := s.Corrections[corrID]; ok {
1236			// 相同标识按目标收款、原因与新月份-金额对应关系判重（列表顺序无关）：
1237			// 内容相同返回原更正记录，不改分配、不增历史；后续更正或收款撤销
1238			// 不影响此规则。任何一项不同（含跨收款复用）均拒绝。
1239			if existing.PaymentID == payID && existing.Reason == reason && sameAllocations(existing.Allocations, allocs) {
1240				fmt.Fprintf(stdout, "更正 %q 已存在且内容相同，返回原更正记录（不改分配、不增历史）：\n\n", corrID)
1241				printCorrection(existing, s)
1242				return nil
1243			}
1244			return fmt.Errorf("更正标识 %q 已存在但内容不同（已有：收款=%s 原因=%q 新分配=%s），拒绝复用",
1245				corrID, existing.PaymentID, existing.Reason, formatAllocations(existing.Allocations))
1246		}
1247	
1248		// 新增更正只允许未撤销收款。
1249		if p.Revoked {
1250			return fmt.Errorf("收款 %q 已撤销（撤销原因 %q），不能新增分配更正", payID, p.RevokeReason)
1251		}
1252	
1253		// 新分配合计必须等于原收款总额（不重复收钱也不多收），全程整数运算。
1254		var sum int64
1255		for _, al := range allocs {
1256			sum, err = add64(sum, al.Amount)
1257			if err != nil {
1258				return fmt.Errorf("新分配金额合计溢出有符号 64 位整数范围，拒绝更正")
1259			}
1260		}
1261		if sum != p.Total {
1262			return fmt.Errorf("新分配合计 %d 分与原收款 %q 的总额 %d 分不一致，拒绝更正", sum, payID, p.Total)
1263		}
1264		// 新分配月份须是原客户的已结算账单。
1265		for _, al := range allocs {
1266			if _, ok := s.Bills[billKey(p.CustomerID, al.Month)]; !ok {
1267				return fmt.Errorf("客户 %s 的 %s 尚无账单（未结算），更正只能分配到已存在账单", p.CustomerID, al.Month)
1268			}
1269		}
1270	
1271		// 以当前最新分配为起点：撤去该笔当前分配再计入新分配后，涉及月份
1272		// 均须满足 0 ≤ 实收 ≤ 应付；其他收款不变，全部合法才整笔生效。
1273		current := currentAllocations(s, p)
1274		for _, m := range unionMonths(current, allocs) {
1275			b := s.Bills[billKey(p.CustomerID, m)] // 载入时已校验存在
1276			_, payable, err := billTotals(b, adjustmentsFor(s, p.CustomerID, m))
1277			if err != nil {
1278				return fmt.Errorf("客户 %s 的 %s 当前应付异常，拒绝更正: %w", p.CustomerID, m, err)
1279			}
1280			received, err := paymentReceived(s, p.CustomerID, m)
1281			if err != nil {
1282				return fmt.Errorf("客户 %s 的 %s 实收累计异常，拒绝更正: %w", p.CustomerID, m, err)
1283			}
1284			// 该笔收款未撤销，其实收必然包含当前分配，撤去不会变负。
1285			received -= allocAmountFor(current, m)
1286			received, err = add64(received, allocAmountFor(allocs, m))
1287			if err != nil {
1288				return fmt.Errorf("客户 %s 的 %s 更正后实收溢出有符号 64 位整数范围，拒绝更正", p.CustomerID, m)
1289			}
1290			if received > payable {
1291				return fmt.Errorf("更正后客户 %s 的 %s 实收 %d 分将超过当前应付 %d 分，拒绝更正；全部状态保持不变",
1292					p.CustomerID, m, received, payable)
1293			}
1294		}
1295	
1296		c := &correction{
1297			ID:          corrID,
1298			PaymentID:   payID,
1299			Reason:      reason,
1300			Allocations: allocs,
1301			CreatedAt:   time.Now().UTC().Format(time.RFC3339),
1302		}
1303		s.NextSeq++
1304		c.Seq = s.NextSeq
1305		s.Corrections[corrID] = c
1306	
1307		// 更正记录、序号与余额状态在同一次原子保存中持久化；保存失败则
1308		// 一切不生效，该更正标识不被占用。
1309		if err := s.save(); err != nil {
1310			delete(s.Corrections, corrID)
1311			s.NextSeq--
1312			return err
1313		}
1314		fmt.Fprintf(stdout, "已登记收款分配更正 %q（关联收款 %q）：\n\n", corrID, payID)
1315		printCorrection(c, s)
1316		return nil
1317	}
1318	
1319	// unionMonths 返回两个分配列表涉及月份的并集，按月份升序。
1320	func unionMonths(a, b []paymentAllocation) []string {
1321		set := make(map[string]bool, len(a)+len(b))
1322		for _, al := range a {
1323			set[al.Month] = true
1324		}
1325		for _, al := range b {
1326			set[al.Month] = true
1327		}
1328		months := make([]string, 0, len(set))
1329		for m := range set {
1330			months = append(months, m)
1331		}
1332		sort.Strings(months)
1333		return months
1334	}
1335	
1336	// allocationBefore 返回一次更正发生前该收款生效的分配：上一条更正的
1337	// 新分配，或（首次更正时）收款的原始分配。
1338	func allocationBefore(s *state, c *correction) []paymentAllocation {
1339		before := s.Payments[c.PaymentID].Allocations // 载入时已校验存在
1340		var latest *correction
1341		for _, o := range s.Corrections {
1342			if o.PaymentID == c.PaymentID && o.Seq < c.Seq && (latest == nil || o.Seq > latest.Seq) {
1343				latest = o
1344			}
1345		}
1346		if latest != nil {
1347			before = latest.Allocations
1348		}
1349		return before
1350	}
