1352	// printCorrection 输出单笔更正记录：关联收款、标识、原因、完整前后分配，
1353	// 以及前后分配涉及月份的当前余额。
1354	func printCorrection(c *correction, s *state) {
1355		p := s.Payments[c.PaymentID] // 载入时已校验存在
1356		before := allocationBefore(s, c)
1357		fmt.Fprintf(stdout, "更正标识：%s\n", c.ID)
1358		fmt.Fprintf(stdout, "关联收款：%s（客户 %s，总额 %d 分（%s），备注：%s）\n",
1359			p.ID, p.CustomerID, p.Total, moneyFen(p.Total), p.Note)
1360		fmt.Fprintf(stdout, "原因：%s\n", c.Reason)
1361		fmt.Fprintf(stdout, "更正前分配：%s\n", formatAllocations(before))
1362		fmt.Fprintf(stdout, "更正后分配：%s\n", formatAllocations(c.Allocations))
1363		fmt.Fprintln(stdout, "涉及月份当前余额：")
1364		for _, m := range unionMonths(before, c.Allocations) {
1365			b := s.Bills[billKey(p.CustomerID, m)] // 载入时已校验存在
1366			_, payable, _ := billTotals(b, adjustmentsFor(s, p.CustomerID, m))
1367			received, _ := paymentReceived(s, p.CustomerID, m)
1368			fmt.Fprintf(stdout, "  月份 %s：本笔分配 %d 分 → %d 分；当前应付 %d 分（%s），实收 %d 分（%s），未收余额 %d 分（%s）\n",
1369				m, allocAmountFor(before, m), allocAmountFor(c.Allocations, m),
1370				payable, moneyFen(payable), received, moneyFen(received), payable-received, moneyFen(payable-received))
1371		}
1372	}
