1374	// --- 账后对账流水 ---
1375	
1376	// ledgerEvent 是某张已结算账单账后流水中的一个事件：调整、撤销调整、收款、
1377	// 分配更正或撤销收款。事件按全局操作序号升序回放；撤销在其发生序号抵消
1378	// 对应原操作，已撤销记录在撤销之前仍计入，不按当前撤销状态删除原事件；
1379	// 更正在其发生序号把关联收款在本账单的分配由前值替换为后值。
1380	type ledgerEvent struct {
1381		seq           int64  // 全局操作序号（调整/收款/更正及其撤销共用）
1382		kind          string // 事件类型：调整 / 撤销调整 / 收款 / 更正 / 撤销收款
1383		refID         string // 原记录标识（调整标识、收款标识或更正标识）
1384		deltaPayable  int64  // 对当前应付的影响（分，带符号）
1385		deltaReceived int64  // 对实收的影响（分，带符号）
1386		note          string // 原因（调整/更正类）或备注（收款类）
1387		linkSeq       int64  // 撤销事件关联的原操作序号；非撤销事件为 0
1388		payTotal      int64  // 收款类事件：汇款总额
1389		payAlloc      int64  // 收款类事件：本账单分配（撤销收款事件为被取消的最新分配）
1390		payID         string // 更正事件：关联收款标识
1391		beforeAlloc   int64  // 更正事件：本账单更正前分配
1392		afterAlloc    int64  // 更正事件：本账单更正后分配
1393		afterPayable  int64  // 事件后的应付（回放时填充）
1394		afterReceived int64  // 事件后的实收（回放时填充）
1395	}
1396	
1397	// billLedger 把目标账单的调整、调整撤销、收款、分配更正与收款撤销合并为
1398	// 一条按操作序号升序的流水，并以原总金额为初始应付、零实收为起点逐步回放，
1399	// 填充每个事件之后的三项余额。回放覆盖完整流水（不受查询截止序号限制）：
1400	// 序号重复、撤销先于原操作，或任一事件之后不满足 0 ≤ 实收 ≤ 应付 ≤ 有符号
1401	// 64 位最大值，都视为数据异常并拒绝——只检查最终余额会放过中间越界的存档。
1402	// 只读：不修改库、不占用序号、不新增记录。
1403	func billLedger(s *state, b *bill) ([]ledgerEvent, error) {
1404		var events []ledgerEvent
1405		for _, a := range s.Adjustments {
1406			if a.CustomerID != b.CustomerID || a.Month != b.Month {
1407				continue
1408			}
1409			events = append(events, ledgerEvent{
1410				seq: a.Seq, kind: "调整", refID: a.ID,
1411				deltaPayable: a.Amount, note: a.Reason,
1412			})
1413			if a.Revoked {
1414				neg, err := neg64(a.Amount)
1415				if err != nil {
1416					return nil, fmt.Errorf("调整 %q 的金额 %d 分无法抵消（越界），数据异常，拒绝输出流水", a.ID, a.Amount)
1417				}
1418				events = append(events, ledgerEvent{
1419					seq: a.RevokeSeq, kind: "撤销调整", refID: a.ID,
1420					deltaPayable: neg, note: a.RevokeReason, linkSeq: a.Seq,
1421				})
1422			}
1423		}
1424		for _, p := range s.Payments {
1425			if p.CustomerID != b.CustomerID {
1426				continue
1427			}
1428			// 多月汇款只以本账单分配改变实收；更正在其发生序号把本账单分配
1429			// 由前值替换为后值；整笔撤销在同一序号取消撤销时的最新分配。
1430			// 首次登记或任一次更正涉及本账单的，该收款的后续事件都纳入流水。
1431			alloc := p.amountFor(b.Month)
1432			corrs := correctionsFor(s, p.ID)
1433			involved := alloc > 0
1434			if !involved {
1435				for _, c := range corrs {
1436					if allocAmountFor(c.Allocations, b.Month) > 0 {
1437						involved = true
1438						break
1439					}
1440				}
1441			}
1442			if !involved {
1443				continue
1444			}
1445			if alloc > 0 {
1446				events = append(events, ledgerEvent{
1447					seq: p.Seq, kind: "收款", refID: p.ID,
1448					deltaReceived: alloc, note: p.Note,
1449					payTotal: p.Total, payAlloc: alloc,
1450				})
1451			}
1452			running := alloc
1453			for _, c := range corrs {
1454				after := allocAmountFor(c.Allocations, b.Month)
1455				if running == 0 && after == 0 {
1456					continue // 本次更正不涉及本账单
1457				}
1458				events = append(events, ledgerEvent{
1459					seq: c.Seq, kind: "更正", refID: c.ID,
1460					deltaReceived: after - running, note: c.Reason,
1461					payID: p.ID, beforeAlloc: running, afterAlloc: after,
1462				})
1463				running = after
1464			}
1465			if p.Revoked {
1466				events = append(events, ledgerEvent{
1467					seq: p.RevokeSeq, kind: "撤销收款", refID: p.ID,
1468					deltaReceived: -running, note: p.RevokeReason, linkSeq: p.Seq,
1469					payTotal: p.Total, payAlloc: running,
1470				})
1471			}
1472		}
1473		sort.Slice(events, func(i, j int) bool { return events[i].seq < events[j].seq })
1474	
1475		// 逐步回放并核验：只把每个事件的金额影响加到运行余额上，不对发生额
1476		// 做累计求和，因此累计补收/收款发生额超过 64 位上限但每步余额合法时
1477		// 仍能成功。
1478		payable := b.TotalFee
1479		var received int64
1480		seen := make(map[int64]string, len(events))
1481		for i := range events {
1482			ev := &events[i]
1483			desc := ev.kind + " " + ev.refID
1484			if prev, dup := seen[ev.seq]; dup {
1485				return nil, fmt.Errorf("流水序号 %d 重复（%s 与 %s），数据异常，拒绝输出流水", ev.seq, prev, desc)
1486			}
1487			seen[ev.seq] = desc
1488			if ev.linkSeq != 0 && ev.linkSeq >= ev.seq {
1489				return nil, fmt.Errorf("%s 的撤销序号 %d 不晚于原操作序号 %d，数据异常，拒绝输出流水", desc, ev.seq, ev.linkSeq)
1490			}
1491			var err error
1492			if payable, err = addSigned64(payable, ev.deltaPayable); err != nil {
1493				return nil, fmt.Errorf("序号 %d（%s）之后应付越出有符号 64 位整数范围，数据异常，拒绝输出流水", ev.seq, desc)
1494			}
1495			if received, err = addSigned64(received, ev.deltaReceived); err != nil {
1496				return nil, fmt.Errorf("序号 %d（%s）之后实收越出有符号 64 位整数范围，数据异常，拒绝输出流水", ev.seq, desc)
1497			}
1498			if payable < 0 {
1499				return nil, fmt.Errorf("序号 %d（%s）之后应付为 %d 分（小于 0），数据异常，拒绝输出流水", ev.seq, desc, payable)
1500			}
1501			if received < 0 {
1502				return nil, fmt.Errorf("序号 %d（%s）之后实收为 %d 分（小于 0），数据异常，拒绝输出流水", ev.seq, desc, received)
1503			}
1504			if received > payable {
1505				return nil, fmt.Errorf("序号 %d（%s）之后实收 %d 分超过应付 %d 分，数据异常，拒绝输出流水", ev.seq, desc, received, payable)
1506			}
1507			ev.afterPayable = payable
1508			ev.afterReceived = received
1509		}
1510		return events, nil
1511	}
1512	
1513	func cmdBillLedger(dir, customerID, month, cutoffText string, hasCutoff bool) error {
1514		if !validMonth(month) {
1515			return fmt.Errorf("月份 %q 无效，必须是 YYYY-MM 形式（如 2026-09）", month)
1516		}
1517		s, err := loadStore(dir)
1518		if err != nil {
1519			return err
1520		}
1521		cust, ok := s.Customers[customerID]
1522		if !ok {
1523			return fmt.Errorf("客户标识 %q 不存在", customerID)
1524		}
1525		b, ok := s.Bills[billKey(customerID, month)]
1526		if !ok {
1527			return fmt.Errorf("客户 %s 的 %s 尚无账单（未结算）", customerID, month)
1528		}
1529	
1530		// 截止序号使用调整/收款及其撤销共用的已保存全局序号：省略表示最新，
1531		// 0 只返回初始余额，截止包含该序号；因其他客户或月份操作造成的序号
1532		// 空档合法。负数、非整数或超过存档全局序号上限一律拒绝。
1533		cutoff := s.NextSeq
1534		cutoffDesc := "省略，按最新"
1535		if hasCutoff {
1536			v, perr := strconv.ParseInt(strings.TrimSpace(cutoffText), 10, 64)
1537			if perr != nil {
1538				return fmt.Errorf("截止操作序号 %q 不是非负整数: %w", cutoffText, perr)
1539			}
1540			if v < 0 {
1541				return fmt.Errorf("截止操作序号不能为负数，收到 %d", v)
1542			}
1543			if v > s.NextSeq {
1544				return fmt.Errorf("截止操作序号 %d 超过存档全局序号上限 %d", v, s.NextSeq)
1545			}
1546			cutoff = v
1547			cutoffDesc = "指定"
1548		}
1549	
1550		// 先核验目标账单的完整流水：任何异常（即使发生在截止序号之后）都
1551		// 拒绝，不输出部分正常的报告。
1552		events, err := billLedger(s, b)
1553		if err != nil {
1554			return err
1555		}
1556		printBillLedger(b, cust, s.NextSeq, cutoff, cutoffDesc, events)
1557		return nil
1558	}
1559	
1560	func printBillLedger(b *bill, cust *customer, nextSeq, cutoff int64, cutoffDesc string, events []ledgerEvent) {
1561		fmt.Fprintf(stdout, "账单标识：%s\n", b.ID)
1562		fmt.Fprintf(stdout, "客户：%s（%s）\n", cust.ID, cust.Name)
1563		fmt.Fprintf(stdout, "月份：%s（UTC 自然月，左闭右开）\n", b.Month)
1564		fmt.Fprintf(stdout, "原总金额：%d 分（%s）\n", b.TotalFee, moneyFen(b.TotalFee))
1565		fmt.Fprintf(stdout, "存档全局序号上限：%d\n", nextSeq)
1566		fmt.Fprintf(stdout, "截止操作序号：%d（%s）\n", cutoff, cutoffDesc)
1567		fmt.Fprintf(stdout, "初始余额：应付 %d 分（%s），实收 0 分（%s），未收余额 %d 分（%s）\n",
1568			b.TotalFee, moneyFen(b.TotalFee), moneyFen(0), b.TotalFee, moneyFen(b.TotalFee))
1569	
1570		// 截止包含该序号；截止之后的事件（含撤销）既不出现也不影响历史余额。
1571		payable, received := b.TotalFee, int64(0)
1572		var shown []ledgerEvent
1573		for _, ev := range events {
1574			if ev.seq > cutoff {
1575				continue
1576			}
1577			shown = append(shown, ev)
1578			payable, received = ev.afterPayable, ev.afterReceived
1579		}
1580		if len(shown) == 0 {
1581			fmt.Fprintln(stdout, "流水：无（截止序号以内该账单无账后事件）")
1582		} else {
1583			fmt.Fprintln(stdout, "流水（按操作序号升序）：")
1584			for i, ev := range shown {
1585				fmt.Fprintf(stdout, "  %d. %s\n", i+1, formatLedgerEvent(ev))
1586			}
1587		}
1588		fmt.Fprintf(stdout, "截止时余额：应付 %d 分（%s），实收 %d 分（%s），未收余额 %d 分（%s）\n",
1589			payable, moneyFen(payable), received, moneyFen(received), payable-received, moneyFen(payable-received))
1590	}
1591	
1592	// formatLedgerEvent 渲染一条流水事件：序号、类型、原记录标识、金额影响、
1593	// 原因或备注、撤销关联，以及事件后的应付、实收、未收余额；收款类事件同时
1594	// 说明汇款总额与本账单分配。
1595	func formatLedgerEvent(ev ledgerEvent) string {
1596		after := fmt.Sprintf("事后：应付 %d 分，实收 %d 分，未收余额 %d 分",
1597			ev.afterPayable, ev.afterReceived, ev.afterPayable-ev.afterReceived)
1598		switch ev.kind {
1599		case "调整":
1600			return fmt.Sprintf("序号 %d 调整 %s：应付 %+d 分（%s，%s），原因：%s → %s",
1601				ev.seq, ev.refID, ev.deltaPayable, moneyFen(ev.deltaPayable), adjustKind(ev.deltaPayable), ev.note, after)
1602		case "撤销调整":
1603			return fmt.Sprintf("序号 %d 撤销调整 %s：应付 %+d 分（%s，关联序号 %d 的调整 %s），原因：%s → %s",
1604				ev.seq, ev.refID, ev.deltaPayable, moneyFen(ev.deltaPayable), ev.linkSeq, ev.refID, ev.note, after)
1605		case "收款":
1606			return fmt.Sprintf("序号 %d 收款 %s：实收 %+d 分（%s，汇款总额 %d 分，本账单分配 %d 分），备注：%s → %s",
1607				ev.seq, ev.refID, ev.deltaReceived, moneyFen(ev.deltaReceived), ev.payTotal, ev.payAlloc, ev.note, after)
1608		case "更正":
1609			return fmt.Sprintf("序号 %d 更正 %s：实收 %+d 分（%s，关联收款 %s，本账单分配 %d 分 → %d 分），原因：%s → %s",
1610				ev.seq, ev.refID, ev.deltaReceived, moneyFen(ev.deltaReceived), ev.payID, ev.beforeAlloc, ev.afterAlloc, ev.note, after)
1611		default: // 撤销收款
1612			return fmt.Sprintf("序号 %d 撤销收款 %s：实收 %+d 分（%s，关联序号 %d 的收款 %s，汇款总额 %d 分，取消本账单分配 %d 分），原因：%s → %s",
1613				ev.seq, ev.refID, ev.deltaReceived, moneyFen(ev.deltaReceived), ev.linkSeq, ev.refID, ev.payTotal, ev.payAlloc, ev.note, after)
1614		}
1615	}
1616

