	if out = h.mustRun("plan", "schedule", "c9"); !strings.Contains(out, "固定单价客户") {
		t.Fatalf("固定单价客户安排查询异常:\n%s", out)
	}
	h.runExpectErr("plan", "schedule", "ghost")
	h.runExpectErr("plan", "schedule", "c1", "2026-13")
}

