// 月累计数量、分档金额或总额溢出时返回错误。
func buildTieredBill(s *state, cust *customer, month string, recs []*usageRecord) (*bill, error) {
	p := s.Plans[s.effectivePlanID(cust, month)] // 载入时已校验存在
	priced, err := tieredPrice(p.Tiers, recs)
	if err != nil {
