	for i := range p.Tiers {
		tierTotals[i] = tierTotal{Quantity: priced.tierQty[i], Fee: priced.tierFee[i]}
	}
	// 账单保存方案标识、名称与完整规则快照，之后计价与校验只依赖账单自身。
	tiersCopy := make([]tier, len(p.Tiers))
	copy(tiersCopy, p.Tiers)
	return &bill{
		ID:         stableBillID(cust.ID, month),
		CustomerID: cust.ID,
